// Файл згенеровано scripts/build_tlumach.py з scripts/zigaben/uk/, не правте вручну.
import type { TlumPsalms } from './index';
// Кафизма 19: псалми 134–142.
export const Z: TlumPsalms = {"134":[{"v":"0","t":["Алилуя.","Про напис «Алилуя» ми говорили раніше, а саме, що псалми, які мають цей напис, — подячні Богові.","Прим.: За словами Євсевія, «алилуя» означає: хваліть Господа; бо «алилу» означає «хваліть», а «я» — «Господа»; тому цей псалом містить пісню й хвалу Богові; він же містить ще й початкове вчення, якого потребують ті, хто приходить до Божого слова з язичників; на них і поширюється це повеління, як на рабів, що ще не дістали Духа всиновлення й не ввійшли до найвнутрішнішої частини дому, а ще стоять поза тією частиною, до якої мають увійти тоді, коли стануть синами через Духа."]},{"v":"1","t":["Усі, каже, раби Господні, і як Його творіння, і як вірні та свої Йому, славте ім'я Господнє, бо воно освячує й благословляє тих, хто його благословляє. Але про це ми сказали й у 102-му псалмі.","Прим.: Слова Феодорита: оскільки єство Боже невидиме, а Він велить хвалити Його, то влучно сказав: хваліть ім'я Господнє; задовольняйтеся, каже, одним найменуванням Бога й не домагайтеся побачити те, чого не дозволено бачити."],"h":"Хваліть ім'я Господнє, хваліть, раби Господні"},{"v":"2","t":["Те саме сказав і в попередньому псалмі. Але тепер, спонукаючи всіх, хто входить до храму Божого, каже: прославляйте Бога, ви, що стоїте в храмі Божому, бо тим, хто не стоїть у храмі Божому, не дозволено хвалити Бога. Чому? Бо ті, хто бачить храм і в ньому Святе Святих, що є оселею Божою, ніколи не забувають Бога, а, навпаки, спонукаються до Його хвали.","Прим.: Цей мудрий тлумач цими словами не забороняє нікому хвалити Бога, коли він перебуває і в Його домі, і в будь-якому іншому місці, а заохочує ними християн іти до храму Божого й там молитися з іншими своїми братами, коли не заважає їм жодна потреба, ні хвороба, ні щось інше: бо молитва, яку християни приносять Богові одноголосно, буває Йому приємніша. Тому Золотоустий, пояснюючи це місце, каже: а якщо й уночі слід ходити до святині, то подумай, яке прощення дістане той, хто й удома в цей час не звершує молитви. Бо якщо в юдейському храмі не кожне місце було доступне для всіх, а були різні відділи, так що одне було призначене для прибульців, інше — для тих, хто був юдеями від початку, ще інше — для священиків, і ще інше — для самого архієрея, то подумай, яку святість потрібно мати тобі, що дістав набагато більше, ніж мало образів Святе Святих? Ти вже маєш не херувимів, а Самого Господа херувимів, що живе тут; і не посудину з манною, і не кам'яні скрижалі й Ааронів жезл, а Тіло й Кров Владики, і замість письмен — Духа. А що більших і страшніших таїнств ти сподобився, то більше зобов'язаний зберігати святість і то більшій кари підлягаєш, якщо переступиш те, що тобі звелено. Євсевій: добре сказано — стояти в домі Господньому й не хитатися, не відступати назад, а виявляти ревність до ходіння всередину. Феодорит: звільнившись, каже, від вавилонського рабства й досягнувши бачення краси Божих дворів, прославте піснями Подателя цих благ."],"h":"Ви, що стоїте в храмі Господньому, у дворах дому Бога нашого"},{"v":"3","t":["Славте, каже, Господа за Його людинолюбство, за те, що Він дуже благодійний для всіх, а особливо для тих, хто хвалить і славить Його. Співайте, веде далі, імені Господньому, бо добре й корисно співати Господеві духовні пісні й псалми; коли їх співають з розчуленням і благоговінням, вони навчають тих, хто співає й слухає, точності догматів, збирають до Бога, присипляють пристрасті, втішають злагодженістю душу й разом з користю, за словами Золотоустого, дають і приємність, і насолоду. Як ті, хто має любов до когось, складають якісь похвали й пісні йому, співом і читанням яких, за Золотоустим, задовольняють своє бажання, так і Давид, радячи співати, цим показує, що ті, хто співає й слухає, мають мати велику любов до Бога. До того ж сказав «співайте» не Божому єству, бо воно незбагненне, а Його імені, складаючи Йому хвали.","Прим.: Феодорита: приводом до співу, каже, зробіть благість Того, Кому співається пісня.","Прим.: Інший тлумач переклав: співайте імені Його, бо це пристойно, а ще інший: бо це солодко. І обидва вони, за словами Золотоустого, кажуть правду. Бо хоч би той, хто співає, був безмірно хтивий, соромлячись слів цього псалма, він приборкає жорстокість хтивості; хоч би був обтяжений незліченними лихами й охоплений смутком, захоплюючись приємністю, він полегшить свої думки, окрилить свій розум, зробить душу піднесеною. А псалтир, за словами Євсевія, — це людське тіло, складене з різних чуттів, ніби з різних струн, через яке розум людини, граючи злагоджено й правильно, звершує те, що стосується доброчесного життя. Отже, оскільки співати, каже, тобто славити ділами Бога, — добре, то приносьте Йому належну пісню через псалтир і тілесні члени."],"h":"Хваліть Господа, бо добрий Господь; співайте імені Його, бо це гарно"},{"v":"4","t":["Тут Давид викладає причину, з якої слід співати Господеві: вона полягає в тому, що Господь з усіх народів вибрав юдейський народ, що походить від патріарха Якова, і його відокремив для Себе, щоб він служив тільки Йому одному. Той самий юдейський народ тут називає Ізраїлем, бо він походить від Ізраїля, тобто від Якова: бо той самий, що раніше звався Яковом, згодом, за своїм поступом у Бозі, як пояснює Великий Василій, був названий і Ізраїлем. Юдейський, каже, народ Бог вибрав Собі у власність, тобто в спадщину й набуток Свій; тому Бог і назвав його Своїм власним народом: будете, каже, Мені власним народом (Вих. 19:5), тобто скарбом, улюбленим предметом Його піклування, мов майно й багатство."],"h":"Бо Якова вибрав Собі Господь, Ізраїля — на власність Собі"},{"v":"5","t":["Тут Давид подає й іншу причину, з якої мають хвалити Бога й співати Йому всі давні й нові ізраїльтяни, тобто християни: вона, каже, полягає в тому, що я більше за вас і точно збагнув, що Господь великий; а це я пізнав і від божественної благодаті, що мене просвітила, і через розглядання розумом Його діл і чудес. Господь, що шанується нами як Бог, — сущий, тобто справжній, а боги, так звані в еллінів, зовсім не існують; і Господь наш — справжній Господь, а боги еллінів не справжні. Далі слово «понад» тут, на перший погляд, ужите Давидом порівняльно, але це з передбачливістю, тобто, як зауважує Золотоустий, щодо грубості й низькості пізнання юдейського народу; а в інших місцях він називає Його Господом і Богом богів: Бог богів, Господь, промовив (Пс. 49:1); і в цьому ж псалмі, поступово підносячи слухачів до справжнього пізнання Бога, представляє Його Творцем і Звершителем чудес, а далі ганьбить язичницьких богів. І в 96-му псалмі сказано також: Ти дуже піднісся над усіма богами; там і дивись пояснення цих слів.","Прим.: Золотоустого: скажи ж мені: ти пізнав, а хіба інші не знали? Так, знали, каже, але не так, як я; бо точніше знання Його величі належить особливо святим і тим, хто піднісся, і то не все, як воно є, бо це неможливо, а ясніше, ніж іншим. Феодорита: з самих, каже, діл ми пізнали силу нашого Бога й те, що шановані в інших народів боги аж ніяк не можуть зрівнятися з Ним; бо ніхто не порівнює неіснуючого з існуючим і вічносущим."],"h":"Бо я пізнав, що великий Господь, і Господь наш — понад усіма богами"},{"v":"6","t":["Те саме сказав у 113-му псалмі: Бог наш на небі й на землі; усе, що схотів, сотворив. Давид морями називає різні затоки одного моря, бо збори вод Бог назвав морями (Бут. 1:10). А безоднями називає підземні, недосліджені. Усередині, каже, тих і інших Бог сотворив тварин, рослин, одушевлені й бездушні речі, що в них містяться, які Йому було вгодно. Далі він прославляє деякі дивовижні Божі діла, залишивши більші, щоб і з нижчих творінь показати велич і пам'ятність Творця.","Прим.: Феодорита: з цим згідне таке: з величі й краси творінь за міркуванням можна бачити Причину їхнього буття (Прем. 13:5); а також апостольські слова: бо невидиме Його від створення світу стає видимим через розглядання творінь. І Давид тепер із творіння показує Божу силу й каже, що їх створення відповідає не силі, а Його бажанню: бо Він міг створити багато разів стільки ж творінь і набагато більших, але Йому було вгодно створити стільки й таких властивостей. Золотоустого: і, що особливо дивовижно, Він сотворив без праці й напруги, не за наказом, а одним бажанням: варто було тільки захотіти — і раптом сталося саме діло. І як у нас бажання не спричиняє втоми, так і в Нього — створення стількох і таких великих сил. Це й пророк показав, кажучи: усе, що схотів, сотворив на небі й на землі. Чи бачиш, що не тільки для створення земних, а й для творення небесних сил досить було одного Його бажання? Чи помічаєш, як водночас представив і легкість, і рясноту творінь, і безперешкодну владу? Орігена: усі Господні творіння на небі й на землі, у морях і в безоднях, як такі, що постали з Божої волі, добрі. А хоч би хтось і став злим на небі, як-от духи злоби, чи на землі, як-от грішні люди, чи в морях, як злоба змія, чи в безоднях, як лукавство тих, кому звелено туди йти, — але цього зла Бог не сотворив за Своїм бажанням: бо з уст Всевишнього не може виходити і зло, і добро (Плач 3:38).","Прим.: Феодорита: безоднями називає безмірну безліч вод, а моря назвав у множині тому, що одне море ділилося на багато морів, як-от на затоки: Атлантичну, Тірренську й Іонічну, Егейську, Аравійську, Індійську, Евксинську та інші моря."],"h":"Усе, що схотів Господь, сотворив на небі й на землі, у морях і в усіх безоднях"},{"v":"7","t":["Господь, веде далі, Своїм промислом підіймає з найглибших місць землі хмари й так високо підносить їх у повітря за всієї їхньої природної ваги, і Він робить так, що вода, яка є в горішніх повітряних просторах, ллється з хмар, коли вони, згустившись, стануть важчими за повітря, що їх тримає. Бог, додає, творить під час дощу блискавки і влаштовує злагоду між протилежними речами, що знищують одна одну, без шкоди однієї від іншої, тобто так, що ні блискавка, попри свою вогненну й найполум'янішу властивість, не знищує й не висушує дощової води, ні, навпаки, дощова вода своїм швидким поривом не гасить блискавки, за Золотоустим і Феодоритом. Бог, додає, виводить вітри зі Своїх скарбниць; скарбницями називає приховані місця, з яких виходять вітри, бо скарб прихований; а образом скарбу Давид виражає невідомість походження вітрів. Або: виводить вітри ніби зі Своїх скарбниць, так що виражається легкість і зручність, з якою Бог, за словами Феодорита, творить їх, коли Йому вгодно. Бо справді дивно, що Бог так легко посилає то один, то інший вітер, або обидва разом, а інколи водночас і більше вітрів; а часто буває, що не посилає жодного, а стан і подих повітря становить тиша й безвітря; і все це Він робить для якоїсь потреби й з передбачливістю, а не без причини й марно, так що в Нього вітри ніби замкнені в якихось скарбницях, з яких Він виводить їх легко й коли Йому вгодно.","Прим.: Того ж: від країв землі, сказав, вони підіймаються, кажучи про це точно; бо вони складаються з морських вод, а краї землі — морські затоки. Бо моря обіймають землю; тому й сказано: що заснував землю на водах. А це сказано й у Йова: зв'язує воду в хмарах Своїх (Йов 26:8). Григорія Богослова: хто зв'язує воду в хмарах? Хто частину її зупинив на хмарах (хіба не дивно для зору, що текуча речовина утримується словом?) і іншу виливає на лице всієї землі й сіє свого часу й рівномірно? Василія: море служить якимсь початком і джерелом повітряних вод, коли нагрівається сонячним промінням і віддає від себе через випаровування тонкі частинки води, які, притягнені в горішній простір, потім охолоджуються. Бо, піднявшись далі, ніж сягає проміння, відбите земною поверхнею, коли в них посилюється холод, а також від тіні хмар, вони стають дощем і живлять землю (Бесіда 4 на Шестоднев, про збирання вод). Також: хмара — густе повітря, що складається з вологого випаровування від землі; потім, піднята вгору вітрами, діставши від них значне скупчення й достатню вагу через вологу, що в ній, вона спускає на землю краплі. Такої властивості дощі, що беруть початок від землі й через повітря знову падають на землю. Золотоустого: так хмари не тільки підіймаються, а й переходять і не в кожному місці, де з'являються, спускають дощ, а інколи, минувши країни й народи, проливають його в іншому місці.","Прим.: Феодорит і Євсевій замість «для дощу» переклали: для приготування дощів і громів, бо за блискавкою зазвичай іде грім. Григорія Богослова: яку можеш запропонувати мені любомудрість про блискавки й громи ти, що гримиш від землі й не блищиш навіть малими іскрами істини? Якісь випари, що виходять із землі й творять хмари, назвеш їхньою причиною? Чи якесь згущення повітря? Чи стиснення й зіткнення найтонших хмар, так що стиснення в тебе творить блискавки, а розрив — грім? І що це за вітер, який стискається, а потім, не знаходячи виходу, від тисняви творить сяйво, а від прориву — грім? Таким питанням і подивом Богослов дає зрозуміти, що ніхто не осягає точно Божих творінь (друге його слово про богослов'я).","Прим.: І Господь сказав про вітер і повітря: вітер віє, де хоче, і голос його чуєш, а не знаєш, звідки приходить і куди йде (Ін. 3:8); бо й вітер — рух, порив повітря; тому й Григорій Богослов сказав: я маю на увазі повітря — це велике, щедре багатство, що не відміряється за гідністю й добробутом, а, подібно до манни, ділиться й приймається вдосталь і подається рівною мірою, — цю колісницю крилатих істот, це сидіння вітрів. А вітри, за словами Золотоустого, різні: один тонший, інший грубіший, один холодніший, інший тепліший, один сухіший, інший вологіший. За новітніми спостереженнями, на Середземному морі віє шістнадцять вітрів, а на океані — удвічі стільки, тобто тридцять два."],"h":"Підіймає хмари від країв землі, блискавки творить для дощу, виводить вітри зі скарбниць Своїх"},{"v":"8","t":["Про це вражання єгипетських первістків ми сказали в 77-му псалмі; там і шукай пояснення слів: проклав стежку гніву Своєму й не пощадив від смерті душ їхніх. А сказавши «аж до худоби», цим виражає надзвичайну кару єгиптян.","Прим.: Золотоустого: що земля, небо й усе видиме користується Його людинолюбством, це показав і пророк згаданими словами. А щоб зробити юдеїв вдячнішими, викладає й подробиці, кажучи, що Бог, промишляючи про всіх загалом, виявив їм і деякі особливі благодіяння. Феодорита: про останню кару згадав першою, бо за нею вже настало їхнє звільнення."],"h":"Він вразив первістків єгипетських від людини до худоби"},{"v":"9","t":["Дивись щодо цього в згаданому 77-му псалмі слова 43-го вірша: як Він учинив у Єгипті знамення Свої й чудеса Свої на полі Цоану. Оскільки Давид вище згадав про десяту й найтяжчу кару — смерть первородних, то слід висновувати, що словами «знамення й чудеса» він за зв'язком указує на інші кари.","Прим.: Що означає «посеред тебе»? — каже Золотоустий. Відкрито, як каже й в іншому місці: учинив спасіння посеред землі; бо що посередині, те явне для всіх. І Феодорит: бо царство не могло звільнити фараона від кар, посланих Богом, але того самого лиха зазнали не тільки ті, хто був під правлінням царя, а й цар. Так і великому Мойсеєві сказав Бог усіх: ось Я вражу кожного первістка єгипетського — від первістка фараона, що сидить на престолі, до первістка невільниці, що меле на жорнах (Вих. 11:5)."],"h":"Послав знамення й чудеса посеред тебе, Єгипте, на фараона й на всіх рабів його"},{"v":"10","t":["Бог, каже, умертвив народи, що перешкоджали переходові євреїв і входові в землю обітовану, тобто амаликитян, моавітян, едомлян та інших, або й сім народів, що жили в Палестині. Утім, Давид говорить про це стисло й мимохідь. Бог, розповідає, умертвив правителів і царів вищезгаданих народів."],"h":"Він вразив багато народів і вбив царів могутніх"},{"v":"11","t":["Сигон, цар аморейський, був знаменитий багатством і військами, а Ог був відомий величиною свого тіла й мужністю. Бо розповідається, що він мав залізне ложе, на якому спав, завдовжки дев'ять ліктів, а завширшки чотири лікті. Бог, каже, зруйнував усі царства землі ханаанської, тобто Палестини, у якій один народ жив окремо від інших і звався ханаанським.","Прим.: Мойсей ясно викладає це в Повторенні Закону: бо тільки Ог, цар башанський, залишився з рефаїмів. Ось ложе його — ложе залізне; ось воно в Раббі синів Аммонових: дев'ять ліктів його довжина й чотири лікті його ширина, ліктем людським (Повт. 3:11). А в Євфимія й у Феодорита написано, що його ложе було п'ять ліктів завширшки, — здається, через помилку переписувача.","Прим.: За словами Феодорита: хеттеїв, ханаанеїв, періззеїв, хіввеїв, амореїв, ґірґашеїв, євусеїв і двадцять дев'ять царів; і країни, які вони займали, та їхні міста Він розділив народові єврейському."],"h":"Сигона, царя аморейського, і Ога, царя башанського, і всі царства ханаанські"},{"v":"12","t":["Давид двічі повторив «спадщина», щоб показати її багатство й достаток, ніби сказавши: дав Своєму народові Ізраїлеві землю вищезгаданих народів у спадщину — справді у спадщину.","Прим.: Золотоустого: і це найбільше чудо, що вони змогли не тільки вигнати, а й заволодіти землею й розділити міста, і це дало їм найбільшу насолоду, окрасу, славу. Феодорита: Бог Ізраїлів дав їм, мов якусь батьківську спадщину, ту землю, яку здавна займали ці нечестиві царі."],"h":"І дав їхню землю у спадщину, у спадщину Ізраїлеві, народові Своєму"},{"v":"13","t":["За вищезгадані, каже, чудеса, сотворені Тобою, Господи, Твоє ім'я й пам'ять про Тебе перебуватимуть повік і в усіх родах у євреїв, бо вони дістали благодіяння через ці чудеса.","Прим.: Золотоустого: тут уриває зв'язок мови славослів'ям, що зазвичай роблять святі: коли, почавши говорити про якесь з Божих чудес, вони запалюються, то не раніше закінчують свою мову, ніж прославлять і похвалять Бога за те, про що говорилося, і так задовольняють своє бажання; це особливо робить усюди й Павло. Запалившись невимовним Божим людинолюбством, Давид виголосив славослів'я: Господи, ім'я Твоє повік, тобто слава Твоя безперервна: ніщо не може пошкодити чи перервати її; вона стала, незмінна, непорушна, у повному яскравому світлі. І пам'ять про Тебе, тобто пам'ять, що в Тебе, не скінчиться протягом усіх родів, вона безмежна. І Феодорита: величина сотворених Тобою чудес показала всім Твоє ім'я, і пам'ять про Твої благодіяння збережеться в усіх майбутніх родах."],"h":"Господи, ім'я Твоє повік, і пам'ять Твоя з роду в рід"},{"v":"14","t":["Бог, веде далі, судитиме Свій народ, тобто звершить за нього суд і відплату ворогам, що йому шкодили, і схилиться до Свого народу, який благає й пом'якшує Бога своїми молитвами. Або, за словами Золотоустого, Бог судитиме Свій народ, коли він згрішить, і праведно покарає його, а коли знову покається, Він змилосердиться над ним і допоможе йому.","Прим.: Слова Феодорита: Ти, каже, не знехтуєш нами, з якими перед Твоїм поглядом воюють вороги, і не наведеш кар, на які ми заслуговуємо за наші гріхи, а будеш милостивий і поблажливий. Зауваж же, що ці слова Давид запозичив у Мойсея з його пісні: бо судитиме Господь народ Свій і над рабами Своїми змилосердиться."],"h":"Бо судитиме Господь народ Свій і над рабами Своїми змилосердиться"},{"v":"15","t":["Те саме сказано й у 113-му псалмі; там і дивись пояснення цього. А якщо хтось заперечить, за зауваженням премудрого Фотія, що й наші християнські святі образи — срібло й золото за речовиною й діло рук людських, на це відповідаємо, що хоча й вони — діло рук людських, але не ідоли; бо першообрази ідолів не існували й фальшиві, адже вони представляють вигляд тих богів, які не боги, а біси, що брешуть і вигадують божество; а першообрази наших святих ікон дійсні й справжні, як і іменуються. До того ж ідоли — зображення мерзенних і нечистих, а ікони — образи святих і чистих.","Прим.: Золотоустого: оскільки на початку сказав «Господь наш понад усіма богами» і цим комусь могло видатися, що, кажучи так, пристосовуючись до немочі слухачів, він показує перевагу лише порівняльно, то дивись, як він продовжує слово. Феодорита: назвав їх вище богами, а тепер показує, що вони, будучи без дійсності, позбавляються й самого найменування; він так каже: наш Бог, прекрасні й добрі раби Господні, — Бог усіх, і великий, і Творець, що творить велике; Він сотворив те й те; а боги язичників не тільки не мають творчої сили, а й сам свій вигляд дістали від людського мистецтва, а отже, вони були не що інше, як мертві й глухі ідоли, сутність яких — бездушна речовина, а діло — людське заняття, і їхній вигляд не має жодної дії. Тому й каже золотий святитель, що найбільший докір для тих, хто їм служить, — що вони, будучи й причиною їхнього буття, на них покладають надію свого спасіння."],"h":"Ідоли народів — срібло й золото, діло рук людських"},{"v":"16-17","t":["Те саме сказав і в 113-му псалмі; там і дивись їх пояснення. Тут Давид викладає й причину, з якої язичницькі ідоли безчутні: вони, каже, тобто ці ідоли, не мають подиху життя. Далі Давид поширює цю насмішку над ідолами, щоб ще більше їх присоромити."],"h":"Уста мають — і не говорять, очі мають — і не бачать, вуха мають — і не чують, і немає подиху в устах їхніх"},{"v":"18","t":["Ці слова пояснені в 113-му псалмі; там можеш побачити їхній зміст.","Прим.: Золотоустого: подумай, які ті боги, уподібнення до яких поставлено нарівні з прокляттям; а наше не таке. Бо уподібнення Богові, наскільки це для нас можливо, — найвища межа чесноти й досягнення найвищих благ. Влучно також висловився й Симмах у Євсевія: подібними до них стануть ті, що роблять їх; бо справді ті, хто вдається до бездушних богів, як скам'янілі душею, дійшли до стану тих, кому поклоняються. Феодорита: такої безчутності гідні ті, хто їх робить і їм поклоняється. Бо ті, хто, сам маючи розум, вважає богами тих, хто не має життя й розуму, справедливо стає учасником їхнього нерозуміння."],"h":"Нехай подібні до них будуть ті, що роблять їх, і всі, що надіються на них"},{"v":"19-20","t":["І в 113-му псалмі зробив такий самий поділ народу; там і шукай пояснення цього. Але там написано «дім Ізраїлів надіявся на Господа», а тут — «благословіть Господа», тобто дякуйте Господеві за вищесказані благодіяння, які Він вам зробив. До того ж тут поділив коліно освячених на дві частини: на дім Ааронів, який окремо був першоначальником священних осіб, і плем'я Левія, що був родоначальником і Аарона, і левитів, тобто тих, хто служив, як диякони, у скинії, — роблячи це слово загальнішим і яснішим через Левія.","Прим.: Золотоустого: чому не закликає всіх разом, а з поділом на частини? Щоб ти через це пізнав велику різницю між благословеннями. Інакше благословляє священик, інакше левит, інакше мирянин, інакше численний народ. Благословіть, каже, за ваше звільнення від ворогів, за те, що сподобилися поклонятися Богові. Хоча Він має в Своєму єстві благословення й не потребує хвали інших, утім і ви благословіть, не маючи думки, ніби щось додаєте Йому, а що самі дістаєте від цього користь. Феодорита: вони, каже, приносять бездушним ідолам таке служіння, а ви прославляйте Творця всіх. Далі Давид відокремив левитів (які були дияконами й служителями) від священиків, бо, хоча вони були шанованіші за інших, але нижчі за священиків. Отже, щоб і вони не намагалися захопити собі священичої гідності, як у давнину зважилися на це за проводу богонатхненного Мойсея, конче потрібно було відрізнити їх від священиків. А іншим був чин тих, хто боїться Бога, що походив від Якова й наслідував його благочестя. Далі до благочестивих зараховували й прибульців, тобто прозелітів. І це давало зрозуміти юдеям, що Бог усіх ставить моральну спорідненість вище за знатний рід."],"h":"Доме Ізраїлів, благословіть Господа; доме Ааронів, благословіть Господа; доме Левіїн, благословіть Господа; ті, що боїтеся Господа, благословіть Господа"},{"v":"21","t":["Нехай, підсумовує, Господь буде благословенний і прославлений із Сіону, тобто Той, Хто живе на Сіоні й живе в єрусалимському храмі. Бо там, як говорилося, живе Господь, бо Він розмовляє з очищальника ковчега зі священиками.","Прим.: Золотоустого: хоча Він благословенний за природою, як і існує, але хоче, щоб і ми благословляли Його. Феодорита: Бог, коли Його благословляють, благословить; але Його благословляють словом, а Він благословить самим ділом; і ті, хто прославляє Його, приносять слова, а Він віддає благословення й благодать ділами. А сказав, що Він живе в Єрусалимі, не тому, що обмежує Його природу, а тому, що знав про Його божественне явлення там."],"h":"Благословенний Господь із Сіону, що живе в Єрусалимі"}],"135":[{"v":"0","t":["Алилуя.","І цей псалом одного змісту з попереднім, за зауваженням Феодорита; тому й має той самий напис."]},{"v":"1","t":["Дякуйте, починає, Господеві, раби Господні, за ті самі Його благодіяння, про які згадав у попередньому псалмі. Такий самий початок зробив Давид і в 105-му псалмі, сказавши: сповідуйтеся Господеві, бо Він благий, бо повік милість Його; там це нами пояснено. Понад те, усі вірші цього псалма закінчуються словами «бо повік милість Його» — або для примноження такої Божої милості, або для хвали, щоб справити сильне враження й подив у тих, хто її оспівує.","Прим.: Слова Золотоустого: після кожного вірша додає, мов приспів: бо повік милість Його, тобто не так, як буває з людьми, що інколи благодіють, а інколи перестають. Людям і недуга заважає це робити, і бідність перешкоджає; а Він безперестанно милує, постійно милостивий і ніколи не припиняє цієї справи. Феодорита: принесіть, каже, Богові вдячний спів, згадуючи дані Ним блага й дивуючись Його безмірній милості. Зауважимо тут, що цей псалом власне зветься многомилостивим, тобто полієлейним, від милості, що багато разів згадується в ньому після кожного вірша. А від цього псалма дістав ім'я полієлейного й попередній псалом, тобто «Хваліть ім'я Господнє». І саме панікадило, тобто багатосвічник, що висить посеред церкви, також назване від цього псалма полієлеєм, бо його запалюють під час співу многомилостивого псалма. Тому за кожного співу першого псалма неодмінно слід співати нерозривно за ним і цей псалом, як власне полієлейний, і не можна співати тільки першого без другого, як нерозважливо й погано роблять інші."],"h":"Славте Господа, бо Він добрий, бо повік милість Його"},{"v":"2","t":["Дякуйте, веде далі, Богові, Який є Богом і Владикою над фальшиво іменованими богами й бісами, яким елліни поклоняються як богам; бо хоча біси безчесні й вороги Божі, як перші причини зла й противники Божі, але все ж вони слуги Божі за творінням і в цьому відношенні неминуче підвладні Богові.","Прим.: Євсевія: Він — Бог богів, не тільки бісів, а й тих, про кого сказано: Я сказав: ви боги; а також: богів не лихослов; бо й ангели можуть бути названі богами; тому й апостол каже: бо є багато богів і багато господ на небі чи на землі (1 Кор. 8:5). Орігена: після Трійці так звані боги є такими й звуться такими через причастя Божества (тобто Божої дії й благодаті, а не Божого єства). А Спаситель — Бог не через причастя, а за сутністю. Феодорита: називає богами тих, хто вшанований саном священства, бо вони стали синами Божими. Так і в псалмах: Я сказав: ви боги й сини Всевишнього всі."],"h":"Славте Бога богів, бо повік милість Його"},{"v":"3","t":["Дякуйте, додає, істинному Господеві всіх тимчасових, земних і несправжніх господів, бо наш Господь — Цар царів і Господь господів."],"h":"Славте Господа господів, бо повік милість Його"},{"v":"4","t":["Дякуйте, спонукає, Господеві, Який один сотворив великі чудеса; «один» додано не для відмежування від Сина й Духа, бо Господом називає одного Бога, що шанується в трьох Особах.","Прим.: У Золотоустого пишеться «що творить», у таких його словах: оскільки раніше сказав, що Він — Господь і Владика богів, то на це висловлювання тепер наводить доказ і підтверджує сказане про Нього проповіддю про Його силу. І не сказав «що сотворив», а «що творить», кажучи, що Він благодіє й творить чудеса. До того ж уживає цей дієприкметник двічі, а краще — тричі й чотири рази: і що Він творить, і що творить чудеса, і що великі чудеса, і що творить один. Бо, за зауваженням Феодорита, і чудеса Його друзів і угодників — Мойсея, Ісуса Навина й Іллі — належать Богові. Для чого ж на початку (питає Золотоустий) Давид не говорив про могутність, що слід благословляти Бога за неї, а за те, що Він добрий? Чому ж тепер раптом почав говорити про силу? Тому, що ці чудеса показують не тільки силу, а й благість і людинолюбство."],"h":"Тому, Хто один творить великі чудеса, бо повік милість Його"},{"v":"5","t":["Дякуйте, радить, Господеві, Який премудрістю сотворив небеса; цими словами Давид свідчить про благість і милість, що в Бозі, і про панування над усіма, і про силу та премудрість, які Бог має за природою.","Прим.: Василія: з цими словами згідні такі: Бог премудрістю заснував землю, утвердив небеса розумом. А розум, яким приготовлені й утверджені небеса, — який може бути інший, як не Христос? Бо Христос — Божа сила й Божа премудрість. Золотоустого: сотворив не одне тільки небо, а й інше, від самого початку показуючи цим, що Він не хоче залишити нас на землі, а переселити туди. Бо якби в Нього не було наміру переселити туди, то для чого Він створив за Своїм бажанням небо? Бо Йому ця стихія не потрібна; але, бажаючи переставити туди тих, хто на землі, Він приготував для них оселі."],"h":"Тому, Хто сотворив небеса мудрістю, бо повік милість Його"},{"v":"6","t":["Дякуйте, навчає, Господеві, Який утвердив землю на водах; і про це дивись у 23-му псалмі слова «Він на морях заснував її», і там знайдеш пояснення цього місця.","Прим.: Золотоустого: яка дивна властивість і понадприродний порядок у цьому творінні! Бо за порядком природи — щоб вода трималася на землі, а не земля на водах. До того ж як часто малому каменю, що впав у воду, вона поступається, розступається й пропускає його в саму безодню. Отже, коли ти побачиш, що не малий камінь, а вся земля тримається на поверхні вод і не тоне, то подивуйся силі, що так понадприродно це влаштувала. Євсевія: що найдивовижніше — земля, стихія щільна й важка, носиться й пливе на водах, тоді як ці тіла не такої властивості; бо мокрі, як легші за землю, мають триматися вище за неї, а вона, як стихія важка й груба, має опускатися й ховатися під глибинами мокрого тіла. Але в складі світу робиться не це, а навпаки, всупереч законові природи."],"h":"Тому, Хто утвердив землю на водах, бо повік милість Його"},{"v":"7-9","t":["Дякуйте, каже, Господеві, Який сотворив два великі світила: світило більше — для панування над днем, і світило менше — для керування ніччю; і поставив їх Бог на небесній тверді, щоб світили на землю й керували днем і ніччю (Бут. 1:16–18).","Прим.: Феодорита: влучно з кожним словом піснописець поєднує вічну милість, бо Людинолюбець сотворив усе не з потреби, а з однієї благості. Золотоустого: те, що створені такі великі світила, прекрасні й достатні, показує силу й премудрість, а те, що створені для нас і для нашої користі, — явно відкриває вічну благість. Василія: ці світила великі не тому, що більші за менші зорі, а тому, що мають обсяг, достатній для того, щоб промінням, яке з них виливається, осявати небо й повітря й водночас поширюватися на всю землю й море. Його ж: одне — благодійність світла, а інше — тіло, у якому перебуває світло. Бо це сонце, тобто сонячне коло, і це найсвітліше світло, бувши різними за природою, поєднані силою їхнього Творця. А день — міра часу, протягом якого сонце в півкулі перебуває над землею; а що вдень — тінь, те вночі становить природу темряви. Золотоустого: дивись, яка дивовижність у сонці. Вогонь за природою прагне вгору, завжди сильно підноситься на висоту, постійно рветься; і хоч би ти вжив незліченних способів примусу й насильства, він не може втриматися від прагнення від землі вгору. Так багато разів, узявши запалену скалку й раптом повернувши її вниз, ми не могли змусити вогонь звернути свій порив туди ж: він усе підіймається вище й знизу силкується бігти вгору. А з сонцем Бог учинив зовсім навпаки: Він звернув його проміння до землі й змусив світло прагнути вниз, ніби наказуючи йому так: дивись униз, світи людям."],"h":"Тому, Хто один сотворив світила великі, бо повік милість Його; сонце — для панування вдень, бо повік милість Його; місяць і зорі — для панування вночі, бо повік милість Його"},{"v":"10-12","t":["Дякуйте, навчає, Господеві, Який покарав Єгипет з його первородними синами й худобою і звільнив з-посеред Єгипту Свій народ Ізраїля міцною рукою й раменом, тобто високою рукою, інакше — великою й нездоланною силою; бо ці знамення, що Він їх сотворив у Єгипті, і Його чудеса, і вихід та звільнення єврейського народу були наслідками великої сили.","Прим.: А Феодорит, питаючи, каже: а якщо хтось заперечить: як милість може бути причиною смерті? — то той, хто шукає розв'язання цього, нехай зважить на те, що Він карає кривдників зі співчуття до скривджених; бо милість до ізраїльтян піддала єгиптян карі. І перша, і друга розчинені в Нього правосуддям: і тих Він милує праведно, і цих карає так само праведно. Тому й до того, й до іншого додано: бо повік милість Його. Євсевія: під міцною рукою й простягненим раменом розумій Боже Слово. Золотоустого: а це сказав для того, щоб хтось із недоумкуватіших не подумав, що, коли Він велів їм узяти золото й срібні посудини, то зробив це з безсилля. Бо й це зробив з тим наміром, щоб з усіх боків показатися страшним ворогам і показати, що все може робити повновладно — і обманювати їх, і хитро зводити. Бо як у тому випадку, коли щось робив відкрито, чинив так не тому, що не міг учинити хитро, так і в тому, коли щось зробив хитро, чинив так не тому, що не міг узяти відкрито, а щоб в обох випадках показати Свою силу. А що й це навело страх на іноплемінників, то послухай, що кажуть після того филистимські ворожбити: хіба не тоді, як Він насміявся з них, вони відпустили їх, і ті пішли? (1 Сам. 6:6)."],"h":"Тому, Хто вразив Єгипет з первістками його, бо повік милість Його; і вивів Ізраїля з-посеред них, бо повік милість Його, рукою міцною й раменом простягненим, бо повік милість Його"},{"v":"13-15","t":["Дякуйте, радить, Господеві, Який розділив Червоне море на два відділи, тобто на дві частини; бо Він розділив його надвоє й провів ізраїльський народ посеред нього, а фараона та його військо струсив у нього й потопив їх; струшенням називає вкидання й потоплення, як усе широко викладає книга Вихід: бо струсив, каже, Господь єгиптян посеред моря (Вих. 14:27).","Прим.: Золотоустого разом з Євсевієм: за усним, тобто ненаписаним переданням євреїв, дорога була не одна, а для кожного коліна вода розділялася окремо, так що було дванадцять розтинів і поділів за числом колін. Феодорита: море, поділившись навпіл, замість одного склало два. Бо вода стала для них стіною праворуч і стіною ліворуч. Тому поділ моря надвоє назвав відділами. Але в іншому місці він же погоджується із Золотоустим і Євсевієм і каже: а краще, Бог вирівняв дороги, як, наприклад, ізраїльтянам, як каже Давид: Тому, Хто розділив Червоне море на частини. При цьому деякі додають, що простір розділеного Червоного моря, що тягнувся від одного краю суші до іншого і яким пройшли ізраїльтяни, на думку деяких, був завширшки двісті п'ятдесят стіп, а завдовжки одну лігу, тобто чотири милі, і цей простір євреї пройшли за шість годин. А інші твердять, що Писання назвало поділи в множині за властивістю єврейської мови, яка вживає множину замість однини. Бажаючи, каже Оріген, показати легкість потоплення, ужив вислів «струсив». Золотоустий: зауважте, як разом із силою й обуренням показав і довготерпіння, бо Він доти не винищував їх, хоч вони й були такі безсоромні й уперті, доки вони самі не кинули себе добровільно в погибель. Та сама Божа сила вдихнула в ізраїльтян після розступлення моря сміливість і змусила ступити на цю нову й дивну дорогу; бо оскільки в обох відділах води стояли горами, то для того, щоб не боятися й навіть не підозрювати небезпеки цього переходу, — що моря, нависаючи з обох боків, заллють їх і потоплять увесь народ, — потрібна була висока й мужня душа; тому й Давид сказав: і провів Ізраїля посеред нього."],"h":"Тому, Хто розділив Червоне море на частини, бо повік милість Його; і провів Ізраїля посеред нього, бо повік милість Його; і струсив фараона й військо його в Червоне море, бо повік милість Його"},{"v":"16","t":["Дякуйте, навчає, Господеві, Який провів ізраїльський народ через Червоне море й увів його в пустелю: бо й це введення Богом Свого народу в пустелю й збереження його там, де було стільки причин для його загибелі — голод, спрага, бездощів'я, надмірна спека сонця, безліч диких звірів та інші подібні безіменні небезпеки, від яких Бог зберіг їх неушкодженими, — це, за словами Золотоустого, таке чудо, що було не менше за розділення Червоного моря. Інші чудеса Давид пропускає, залишивши кожному читати про них з роздумом у книгах Мойсеєвих.","Прим.: За словами Золотоустого, Євсевія й Феодорита, і це показує божественну силу, що стільки народу Він протягом такого довгого часу живив у пустелі й водив без лиха, даючи їм з надлишком усе потрібне. Це чудо не менше за проведення через море. Бо, позбавлені всього, чого потребує людина, не маючи ні покрівлі, ні плаща, ні достатньої одежі, ні взуття, ні нічого іншого такого, вони проходили ту пустелю, ніби святкуючи посеред міст."],"h":"Тому, Хто провів народ Свій пустелею, бо повік милість Його"},{"v":"17-20","t":["Прим.: Феодорита: країна Башан — це те, що нині в Юдеї зветься Батанеєю. Пояснення Великого Василія у вищому розумінні: ім'я Башан розуміють у значенні сорому. Тому й цар Башану зветься Огом, що означає загорожа; бо соромні діла загороджують нам дорогу до спасіння. Бо всі, хто чинить соромні діла, перебувають під правлінням царя Ога, що відокремлює їх від Бога (тобто диявола), якого Господь розтрощує для звільнення його підвладних. А Сигон означає спокусу, тобто роздратування. Амореї означають балакучих або тих, що огірчують; їхнє винищення пророк Давид ставить на доказ Божої милості, бо їхню країну через це дано євреям на добре поселення; і це означало обертати багатства нечестивих на скарб праведних (Прип. 13:22). Інший, тобто Никита у Зводі: якщо хочеш бачити, що предивна Божа сила продовжує свою дію й донині, то перейди думкою до народу з язичників, і пізнаєш, як Він звільнив язичницький рід, що увірував у Христа, від гіркого рабства — не в єгиптян, а в лихих бісів, і вивів з єгипетської темряви, і переставив у світло, винищивши невидимих царів і злі сили, що раніше над ними панували, набагато лютіші за фараонових; від них Він і нас звільнив, творячи один великі чудеса Своїм раменом і правицею; про це сказав Ісая: відкриє Господь Бог святе рамено Своє перед усіма народами (Іс. 52:10)."],"h":"Тому, Хто вразив великих царів, бо повік милість Його; і вбив могутніх царів, бо повік милість Його; Сигона, царя аморейського, бо повік милість Його; і Ога, царя башанського, бо повік милість Його"},{"v":"21-22","t":["Усе це пояснено в попередньому псалмі; там і дивись пояснення."],"h":"І дав їхню землю у спадщину, бо повік милість Його; у спадщину Ізраїлеві, рабові Своєму, бо повік милість Його"},{"v":"23-24","t":["Господь, сповідує, згадав про нас, юдеїв, коли ми були пригноблені, тобто страждали в Єгипті: бо добре, каже, бачив Я страждання народу Мого в Єгипті й зійшов, щоб вирвати їх з руки єгиптян (Вих. 3:7–8). А кажучи «нас», Давид цим указує на своїх предків у Єгипті й приймає їх до себе через спорідненість з ними. Далі, залишивши інші окремі благодіяння, які Бог зробив євреям, знову звертається до загального Божого промислу й благодіяння.","Прим.: «В упокоренні нашому» — не в наших подвигах і не в добробуті, а в упокоренні, тобто саме наше нещастя й страждання могло схилити Бога, за словами Золотоустого. Слова Феодорита: про це згадує й Мойсей: застогнали, каже, сини Ізраїлеві від робіт, і зойк їхній зійшов до Бога (Вих. 2:23)."],"h":"Бо в упокоренні нашому згадав нас Господь, бо повік милість Його; і визволив нас від ворогів наших, бо повік милість Його"},{"v":"25","t":["Господь, веде далі, дає належну їжу всякому родові і людей, і всіх тварин — земних, морських і земноводних.","Прим.: Слова Золотоустого: дає їжу не тільки праведникам і тим, хто подвизається в правоті, а й грішникам, і нечестивим, і всьому людському родові. Отже, урожайність залежить не від землі, і не від вод, не від повітря, не від проміння й не від чогось іншого, а все від Нього. І з цього роби висновок не тільки про силу, а й про невимовне людинолюбство. Феодорита: дає їжу не тільки людям, а й безсловесним, відповідно до природи кожного, як сказано: погляньте на птахів небесних: вони не сіють, не жнуть, не збирають у засіки, а Отець ваш Небесний годує їх. Тож Божий промисел такий великий і достатній, що поширюється від чудес на небі до землі й до найменших тварин на ній."],"h":"Тому, Хто дає їжу всякій плоті, бо повік милість Його"},{"v":"26","t":["Дякуйте, підсумовує, Господеві Богові, Творцеві й Владиці неба. А коли Він — Творець неба, то, безперечно, і землі. Або сказав «небесного» тому, що Бог зветься таким, що живе на небі. Ми можемо прикласти і цей, і попередній псалом до себе й спонукати одне одного дякувати Богові, Який по-різному благодіяв Своєму давньому народові, скинув Своїх ворогів і сотворив усі вищезгадані чудеса. А якщо пояснюватимемо цей псалом у вищому значенні, то Яковом і Єрусалимом можна назвати новий, вибраний християнський народ, а Єгиптом — нечестя й гріх; знаменнями й чудесами посеред нього — чудеса, сотворені Христом, апостолами та іншими святими; фараоном — диявола, а рабами фараона — бісів і людей, що служать бісам. Далі вражені й розтрощені численні народи можемо назвати полчищами бісів, а Сигоном та Огом — самого сатану й другого після сатани; ханаанськими царями — гріховні влади. Під їхньою землею, даною новому Ізраїлеві, можемо розуміти ті місця, у яких раніше панували демони й з яких потім вигнані; під домом Ізраїлевим — загалом увесь християнський народ; під домом Аароновим — архієреїв і священиків, а під домом Левіїним — дияконів; під тими, хто боїться Господа, — доброчесних і праведних. Далі під іменем Сіону — Церкву Христову; під первістками єгипетськими — найсолодші й найприємніші пристрасті, як-от особливо тілесні, або те, що особливо бажане для бісів, як і первородні діти бажані для батьків. Під Червоним морем можемо уявляти солодкість і гіркоту нечестивих учень, якими оточуються й тонуть невіруючі й нечестиві; під пустелею — неплідність омани, пройшовши яку й звільнившись від якої благочестиві християни досягають плідної істини. Там же під упокоренням ми маємо розуміти наше християнське смирення — не тільки те, якого нам мимоволі завдають спокуси, а й доброчесне, тобто чесноту смирення, що звершується нашим вільним вибором.","Прим.: Феодорита: отже, Бог — Бог усіх, як Творець усіх; але Він переважно зветься Богом неба, бо особливо шанується служінням ангелів, що там живуть. Бо ця країна чиста від гріха. Отже, за все, каже Золотоустий, віддаваймо Богові подяку — за загальні й за окремі блага; ця жертва, це приношення найбільше може схилити Його до милості до нас."],"h":"Славте Бога небесного, бо повік милість Його"}],"136":[{"v":"0","t":["Псалом Давидів (через Єремію).","Цей псалом мовиться від імені левитів, тобто дияконів, і всього священичого племені та співців, що були полоненими у Вавилоні; і він же передрікає вищезгаданим юдеям, що мало з ними статися, навчаючи водночас, які слова вони мають вимовляти й які діла чинити, щоб ними схилити Бога до милості. У євреїв і він без напису.","Прим.: Зауваж, що, за словами Євсевія, у деяких списках на цьому псалмі є напис: «Аггея й Захарії». А Феодорит зауважує: деякі, зважившись на зухвалу справу, зробили на цьому псалмі напис «через Єремію». Але Єремію не відвели з полоненими до Вавилону, а він, проживши деякий час в Єрусалимі, з примусу беззаконних юдеїв брав з ними участь у переселенні до Єгипту. Тож як він міг казати: на ріках вавилонських, там ми сиділи? І Феофілакт Болгарський у передмові до тлумачення на Йону каже, що богонатхненного Єремію вавилонський цар Навуходоносор ушанував, запропонувавши йому обрати собі місце проживання; і тоді, як усіх інших царів і начальників відвів у полон, йому одному дав волю жити, де захоче."]},{"v":"1","t":["Євреї, як полонені, сиділи й перебували поза містами, тобто в пустельних місцях; тому, часто ходячи на береги рік, там сиділи на самоті й оплакували свій полон і лихо в молінні. Оскільки за часу володіння благами й свободою вони пишалися й зневажали їх своїми гріхами, то й були позбавлені цих благ, щоб знову їх забажали. Бог завжди так чинить з тими, хто зневажає Його блага; і тих людей, що не відчувають і не знають свого добробуту, позбавляє його, щоб, за словами Золотоустого, привести їх до тями й до згадки про нього.","Прим.: Він так каже: коли, насолоджуючись Його благами, ми цього не відчуваємо, тоді Він переселяє нас у пустелю, де немає благ, щоб, напоумившись через їх утрату, ми знову забажали насолоджуватися ними. Феодорит: ті, хто в смутку, зазвичай займають усамітненіші місця й там оплакують своє лихо. Так і вони, сидячи на берегах рік (а під ріками слід розуміти потоки Євфрату) і міркуючи про спустошення свого головного міста, проливали багато сліз, подібних до струменів рік. А за словами Никити, Вавилоном назване те місце, де змішалася мова тих, хто казав: ходімо, збудуймо собі місто й вежу. Там Бог, зійшовши, змішав мови; тому й місце це назване змішанням мов; і Вавилон — місце змішання не тільки мови, а й правил, і думок, і самого розуму, якому здавалося, що він їх бачить."],"h":"На ріках вавилонських, там ми сиділи й плакали, коли згадували Сіон"},{"v":"2","t":["Музичні, каже, знаряддя, на яких ми співали й прославляли Бога, перебуваючи в Єрусалимі, коли нас забрали до Вавилону, ми повісили на вербах, що росли на берегах рік, які течуть у Вавилоні, бо вони тоді були в нас без ужитку й непотрібні. Єврейські співці взяли їх з собою тільки для нагадування собі про єрусалимське богослужіння й життя, як каже Золотоустий. Або у вищому значенні: зупинили, тобто повісили, свої органи на бездіяльності; так що безплідними деревами — вербами — виразили бездіяльність і невживання псалмів та органів.","Прим.: Органи тоді, за словами Феодорита, були без ужитку, бо закон велів звершувати богослужіння й спів тільки в одному місці — Єрусалимі. Євсевій каже, що інші полонені з юдеїв розкошували й не відчували лиха, що їх спіткало; а священики, левити й співці, тікаючи з міста Вавилону й від спілкування зі своїми ворогами — вавилонянами, сиділи на берегах рік і при течії рік міркували про швидкоплинність справ людського життя; і свої органи ховали на берегах, щоб їх не бачили вороги, а самі, сидячи навпроти органів, замість псалмів ридали, оплакуючи те, що позбавлені псалмоспіву на органах і богослужіння. У цьому відношенні ці слова можна прикладати до тих християн, що зрікаються Христа під час гоніння й захоплюються змішанням від гоніння. Бо Вавилон, як ми сказали, — змішання. Отже, коли хтось із християн зазнає змішання гонінь і замість Христової Церкви житиме серед ворогів і нечестивих, то нехай такий ніколи не забуває про Христову Церкву, у якій духовно відродився через хрещення, і нехай не дається Вавилонові в обман, а, сидячи на ріках, тобто міркуючи про плинність і мінливість справ цього життя, нехай плаче й ридає над своїм падінням.","Прим.: Слова Мефодія Патарського: можливо, дівочі чисті душі в піснях Богові кажуть, що на вербах посеред Вавилону ми повісили наші органи, позначаючи цим, що знаряддя, тобто свої оселі й тіла, вони повісили на висоті чистоти, щоб їх не затопили ріки зла, що ринуть на нас, і не захопили до своєї середини, тобто глибини; тому ми й просимо з плачем, щоб ці органи не втратили чистоти й не впали в хвилі хтивості. А верба часто зображує дівство; бо й питво з розтертого її цвіту гасить спонукання до похоті, а інколи й цілком позбавляє прагнення до дітородіння, як і Гомер сказав, назвавши через це верби згубними для плодів. Бо як це дерево зазвичай росте й квітне при водах, так і дівство може квітнути й удосконалюватися тільки тоді, коли живитиметься Писаннями, щоб хтось міг своє знаряддя поставити в залежність від нього. Бо якщо вавилонські ріки, тобто хтиві течії, що приводять до змішання, бентежать душу, то цнотливість, якою ми зв'язуємо лютість дітородних членів, щоб їх не захопили потоки нестриманості й щоб вони не кидалися нестримно, мов хробаки до гнилі й гною, безперечно, має властивість верб.","Слова цього псалма можна розуміти й інакше. А саме: Сіон і Єрусалим — це рай, наша перша батьківщина, а Вавилон — теперішній світ; ріки цього світу — мінливі справи цього життя. Отже, ставши через переступ полоненими бісів, ми вигнані з раю й дійшли до змішання з цим світом. Тому ми завжди маємо пам'ятати блаженне колишнє райське життя й просити Бога повернути нас знову до раю — нашої колишньої батьківщини — і визволити нас з цієї країни вигнання. Тому цей псалом зазвичай співають у тижні перед сиропусним, коли згадується вигнання Адама, щоб виражалася ця думка."],"h":"На вербах посеред нього повісили ми органи наші"},{"v":"3","t":["Вавилоняни, що полонили нас, питали, веде далі, нас, щоб ми сказали їм кілька слів з божественних пісень і хвал, які ми співали Богові в Єрусалимі, тобто наказували нам співати, бажаючи просто послухати для втіхи або й, за словами Феодорита, щоб посміятися з наших святих і божественних речей. Це слова вавилонян, що сказали нам: заспівайте нам, юдеї, якусь пісню з тих пісень, які ви співали, бувши на Сіоні, в Єрусалимі."],"h":"Бо там питали нас ті, що полонили нас, про слова пісень, і ті, що вели нас, — про спів: заспівайте нам з пісень Сіонських"},{"v":"4","t":["А ми, каже, юдеї, відповідали вавилонянам, що нас питали: як нам співати божественну пісню в чужому місці, поза Єрусалимом, коли закон забороняє нам це? Зауваж, читачу, яким корисним був цей полон і як він виправив юдеїв: бо ті, хто раніше переступав закон Божий посеред своєї батьківщини, нині, за словами Золотоустого, бережуть його на чужій землі. А під чужою землею можна розуміти й кожне серце, що відсторонилося від благочестя й чесноти; такому серцю не слід передавати божественних і небесних таїнств, згідно зі сказаним: не давайте святині псам і не кидайте ваших перлів перед свиньми (Мт. 7:6).","Прим.: З двох причин, як каже один тлумач, юдеї не співали перед вавилонянами: по-перше, тому, що поза Єрусалимом не дозволялося навіть звершувати Пасху чи інші свята; а по-друге, якби вони співали й викладали чудеса, сотворені Богом для визволення нас від єгиптян та інших народів, то вавилоняни не повірили б їм, не допускаючи й того рабства, якого зазнавали євреї. Утім, і ті, хто проповідує Євангеліє безумним, за словами іншого тлумача, співають пісню Господню на чужій землі, бо вона не обробляється Христом. І тим, хто відпав від Церкви, також не слід співати пісень, а тільки ридати й говорити мови, що відповідають нещастю, яке їх спіткало. Це може сказати й той, хто пам'ятає слова: а грішникові сказав Бог: навіщо ти розповідаєш постанови Мої? Бо хто відпав від Церкви, той має взяти ці слова до уваги. І Григорій Богослов разом із Золотоустим каже: коли ми захоплені до Вавилону й у лихе гріховне змішання, то, перебуваючи в цьому місці, не можемо співати божественної пісні, як на чужій землі. Бо доки ми поневолені гріхові, найтяжчому з усіх іноплемінників, доти нам не дозволено говорити про щось божественне, хоч би ми мали знаряддя слова, як вони тоді — псалтирі й гуслі. А коли ми повернемося до чесноти, як до Єрусалима, тоді, склавши з себе чи в собі нову пісню й життя, ми співатимемо нову пісню (у Никити). З Феодорита: це служить на викриття беззаконних юдеїв, що намагаються виконувати закон і звершують його приписи поза визначеними законом місцями."],"h":"Як заспіваємо пісню Господню на чужій землі?"},{"v":"5","t":["Якщо я, юдейський народ, забуду, каже, тебе, місто Єрусалиме, то нехай буде забута, за словами Золотоустого, моя сила й моя дія, тобто нехай я сам стану каліцтвом і розслабленим, або нехай усохне моя рука, щоб я більше не відчував її.","Прим.: Слова Золотоустого: і з цього можеш бачити велику переміну: бо ті, хто щодня чув, що втратять місто, і не дбав про це, нині віддають себе прокляттю, якщо забудуть його. Феодорита: нехай я, каже, не дістану допомоги згори, яку називає правицею. А деякі тлумачі кажуть, що євреї, коли втратили свій улюблений Єрусалим і були відведені до Вавилону, так сумували за ним у своєму серці, що для постійної пам'яті про нього вирізали його на каменях своїх перснів і за кожного погляду на перстень, що був на їхній правій руці, мали нагоду згадувати свою жадану батьківщину. Тому й виголосив ці слова у вигляді прокляття: якщо забуду тебе, Єрусалиме, то нехай буде забута моя права рука... Тому й Золотоустий: послухаймо це й напоумимося. Бо як вони, коли втратили вишній, тобто свій Єрусалим, тоді почали шукати його, так і багато з нас повірять тоді, коли втратять горній Єрусалим; але перші мали надію на повернення, а нам, коли позбудемося того жаданого міста, неможливо буде знову повернутися, бо черв їхній там не вмирає, каже Писання. Тож треба так влаштовувати теперішнє життя, щоб не бути вигнанцями з вишнього міста."],"h":"Якщо забуду тебе, Єрусалиме, нехай забута буде правиця моя"},{"v":"6","t":["Нехай, веде далі, відніметься в мене мій голос, щоб я не міг більше говорити, тобто нехай позбудуся сил діяти — ні ділом, ні словом; ділом тут виражається правиця, про яку сказав вище, а прилипанням язика позначається вимовлене слово. Утім, і ми, християни, з любові до вишнього Єрусалима, нашої вічної батьківщини, зобов'язані вимовляти ті самі слова й прокляття. Або правицею називає доброчесну дію, а язиком — споглядання й знання; бо язик — знак і службове знаряддя слова, а слово — вираз споглядання й пізнання. А гортанню позначає пристрасть горла, тобто насолоду. Отже, нехай буде, каже, забута діяльність через бездіяльність і дія споглядання; нехай прилипне до солодких страв і буде без руху щодо насолоди, яку дають божественні пізнання; і ці прокляття дуже тяжкі. Нехай зазнаю, каже, вищеназваних проклять, якщо раніше за все інше не згадуватиму Єрусалима, бо він стоїть на початку всякої моєї радості, тобто він — початок і голова моєї радості, як моя перша насолода.","Прим.: Золотоустого: дієслово «поставлю тебе на початку» означає те саме, що «почну з тебе», — вислів тих, хто має любов, а краще — пожадання, палке прагнення до нього, тобто до Єрусалима. Феодорита: головою, каже, моєї радості вважаю бачення тебе, твоє нове діяння й торжества, що в тобі бувають. Бо через них я здобуваю справжню насолоду."],"h":"Нехай прилипне язик мій до гортані моєї, якщо не згадаю тебе, якщо не поставлю Єрусалима на початку радості моєї"},{"v":"7","t":["Синами Едому називає арабів та ідумеїв, які, за словами Феодорита, походили від Ісава й допомагали вавилонянам у війні з Єрусалимом. І коли вавилоняни руйнували Єрусалим, тоді й араби з великою старанністю заохочували їх зруйнувати самі основи Єрусалима. Отже, згадай, каже, Господи, віддаючи згаданим арабам та ідумеям праведною карою за те, що вони, попри свою спорідненість з нами, євреями, через одне походження від нашого предка Якова, — тобто через його брата Ісава (бо Ісав звався й Едомом, від якого й ідумеї), — стали для нас нестерпнішими за самих наших ворогів і супротивників через заздрість до нас. А сказавши «синам Едому», додав і «день Єрусалима», тобто: згадай, каже, Господи, і синів Едому, і день нещастя Єрусалима, лише змінивши порядок слів і довільно вживши відразу після родового знахідний відмінок. Або каже: згадай синів Едому, що під час лиха Єрусалима допомагали вавилонянам."],"h":"Згадай, Господи, синам Едому день Єрусалима, коли вони казали: руйнуйте, руйнуйте аж до основ його"},{"v":"8","t":["Як у євреїв є звичай називати людину сином людським, так і дочкою Вавилону називають сам Вавилон. Дочко, каже, Вавилону, неправедна! Вавилоне нещасний через лиха, що, як каже Золотоустий, мають тебе спіткати! А такими словами Давид пророкує про винищення, якого він мав зазнати від царя Кира. Ці слова виголошує весь єврейський народ, сильно бажаючи винищення міста своїх ворогів. А відплатою, якою, за висловом, ти відплатила нам, називають завдане зло, тобто спустошення й гноблення, яких ти, Вавилоне, завдав нам, євреям; тут грецький префікс у слові «відплата» зайвий, як ми зауважили й у 7-му псалмі, пояснюючи слова: якщо я відплатив злом тим, хто відплачує мені злом.","Прим.: Дочкою Вавилону зветься столиця Вавилону порівняно з усією вавилонською країною, яка представляється у вигляді матері, а її місто — у вигляді дочки, як ми сказали й у 44-му псалмі, пояснюючи слова «дочка Тиру з дарами», і в 72-му псалмі, пояснюючи слова «у брамах дочки Сіонової».","Прим.: Феодорита: блаженним вважається Кир як той, що покарав їх і звільнив юдеїв, — не за те, що він був вихованцем справжнього благочестя, а за те, що сподобив благочестивий народ свободи й звелів збудувати божественний храм. Далі, Бог приймає й малі плоди й винагороджує великими віддяками. Так Він прославив удовицю за дві лепти. Золотоустого: це вислови пристрасті полонених! Бо якщо хочеш знати налаштування Давида, то послухай, що він каже: якщо я відплатив тим, хто відплачує мені злом (тобто я не відплатив), — і як він стає вище за дозволену законом рівномірність. А коли передає пристрасті інших, то зображує лють і смуток, що й тепер зробив, виставивши сильне бажання юдеїв. Але не такий Новий Завіт: у ньому нам велиться напувати й годувати ворогів і молитися за тих, хто нас кривдить."],"h":"Дочко вавилонська, нещасна! Блаженний, хто віддасть тобі відплату твою, якою ти відплатила нам!"},{"v":"9","t":["Юдеї поширюють свій гнів і на незрілий вік отроків і ублажають того, хто жорстоко й нелюдяно розбив малих дітей і отроків вавилонських. Але євангельські повеління й вдача в нас, християн, як учнів лагідного й людинолюбного Ісуса Христа, не такі — не жорстокі й не нелюдяні. Зовсім не такі, бо наш Владика Христос звелів любити навіть наших ворогів і берегти їх. Але те, що в цьому псалмі може бути легко прийняте у вищому значенні, треба й розуміти в ньому. Отже, під синами Едому ми маємо розуміти бісів, що велять одне одному руйнувати багатства нашої душі до основи. Бо під Єрусалимом маємо уявляти душу. А нещасний Вавилон — це нечестя й гріх, що спустошив і підкорив собі благочестя й чесноту. А хто винищив це нечестя й гріх, той блаженний. Немовлята цього нечестя — новонароджені пристрасні помисли, бо вони дитячі й безтямні. Хто ці помисли перемагає й розбиває об камінь віри (а цей камінь, за словами Павла, — Христос) і так винищує їх, той блаженний.","Прим.: Слова Феодорита: оскільки й вони, вавилоняни, вчинили жорстоко з немовлятами юдеїв, то пророк передрікає їм рівну кару. Василія: у цьому псалмі ублажається не той, хто будь-як убиває вавилонських дітей, а він, по-перше, хоче, щоб винищувалися нещодавно народжені немовлята, яким не дозволено дійти до віку, щоб вони не наробили дуже багато зла; по-друге, щоб їх знищували не будь-яким способом, а розбивали об камінь. Бо він називає щасливим того, хто своєю мудрістю володіє породженнями змішаного розуму, що зветься вавилонським, і переможе їх, а потім велить розбивати їх об камінь, яким є Христос. І хто вражає негідні вчення словом істини, той розбиває вавилонських немовлят об камінь. Отже, якщо діти вавилонян — учення неправославних, бо вони приводять до змішання душу того, хто добровільно їх приймає, то влучно бажає, щоб вавилонські немовлята (які в Писанні звуться винятково й халдейським насінням) були взяті й розбиті об камінь. Кирила: вавилонською дочкою може бути названий і гріх, якщо справді Вавилон, як пояснюють, — змішання, а ділом — переступ розуму, неспокійного й неутвердженого, а краще сказати — того, що прийшов до змішання, злиття й ніби сп'янів від багаторазового схилення до зла. Бо душа спершу приходить до сум'яття, і тоді вже звершує гріх ділом. Слова святого Дорофея: гріх зветься нещасним, бо він не сутнісний і не має справжнього буття, а лише дістає існування від нашої поведінки й знову через чесноту обертається на ніщо. Йому ми віддали свою волю й у відплату дістали гріх, який і має бути йому повернений, тобто більше не чинитися. Вавилонськими немовлятами, що їх ударяють і розбивають об камінь, безпомилково можеш назвати насіння зла й початки гріхів, що спричиняють сум'яття, і пристрасні помисли, що щойно з'являються; їх слід винищувати спасенним словом (бо камінь — Христос), щоб вони не зростали й не доходили до дії, а знищувалися, доки не стали досконалими. Отже, слід виходити ніби з північної землі — з холодного й мертвого налаштування розуму — на Сіон, тобто в істину, щоб мати поняття про Христову Церкву, у якій, перебуваючи, побачимо, що вгодне Богові, і не дамо злу в нас ні початку, ні місця, де б воно могло зрости й дійти до дії, а будемо блаженні, пануючи над дитячими й безтямними помислами, розбиваючи й так гублячи їх об камінь віри (у Никити)."],"h":"Блаженний, хто візьме й розіб'є немовлят твоїх об камінь!"}],"137":[{"v":"0","t":["Псалом Давидів (Аггея й Захарії).","Прим.: Цей псалом — подяка Богові після повернення з Вавилону від імені юдеїв, що звільнилися, за словами Феодорита й Євсевія, від народів, які на них повставали. Цей псалом містить і пророцтво про покликання народів. В інших на ньому такий напис: «Псалом Давидів, Аггея й Захарії»."]},{"v":"1","t":["Цими словами Давид починає й 9-й псалом. Перед ангелами, обіцяє, співатиму Тобі, Господи, тобто разом з горніми й небесними силами співатиму Тобі і я, дольній і земний; бо хвалити Тебе безперестанно — справа ангельська. Або ангелами називає священиків, бо Писання зазвичай називає священиків богами й ангелами: то кажучи через Малахію: уста священика бережуть знання, і закону шукають з уст його, бо він — ангел Господа Вседержителя (Мал. 2:7), то через Мойсея: богів не лихослов і начальника в народі твоєму не проклинай (Вих. 22:28). А інший тлумач переклав так: перед богами співатиму Тобі. Співатиму Тобі, додає, Господи, за те, що Ти вислухав усе моє прохання, виконавши його в тому, що належало.","Прим.: Слова Золотоустого: перед ангелами, тобто з ангелами підноситиму пісню, намагаючись змагатися з ними й ликуючи з горніми силами. Бо хоча за природою ті й інші різняться, але ревністю я постараюся стояти разом з ними. Або: співатиму благоговійно, уявляючи собі ангелів, що тут присутні й дивляться.","Прим.: Золотоустого: чи бачиш велику вдячність? Не так, як інші — мляві й слабкі, що до одержання ревні, а після одержання недбалі, а він і до одержання старанний, і після одержання залишається завжди вдячним."],"h":"Прославлю Тебе, Господи, усім серцем моїм і перед ангелами співатиму Тобі, бо Ти почув усі слова уст моїх"},{"v":"2","t":["Віддам, каже, Тобі, Господи, борг моєї подяки поклонінням Твоєму святому храмові — і за Твоє помилування мене, і за помилування справжнє. Бо така думка в словах «за милість Твою й істину Твою», тобто за Твою істинну милість, за властивістю єврейської мови, що вживає прикметники у вигляді іменників, як ми вже зауважили й в іншому місці. Або: буду вдячний Тобі за правдивість Твоєї обітниці. Дякуватиму Тобі, Господи, веде далі, і за те, що Ти явив Своє ім'я в кожній справі великим і дивним, бо все сотворене Тобою проповідує велич Твого імені. Інший тлумач переклав: бо Ти звеличив понад усе.","Прим.: Того ж: немала й це чеснота — коли хтось може ходити до храму й, прийшовши, поклонятися з чистою совістю. Бо потрібне не схиляння колін, не входження, не тільки це, а щоб перебувати в ньому з палкою душею й напруженою думкою, бути не тільки тілом, а й розумом. Також немало гідності в належному поклонінні Всевишньому Богові. Бо якщо це становить гідність щодо царів, то набагато більшу щодо Всевишнього Бога. А слова «за милість Твою й істину Твою» інший тлумач переклав так: дякуватиму Тобі за звільнення мене з полону й за те, що сподобив істини, що я позбувся образів і тілесного богослужіння й навчився поклонятися Богові духом і істиною. Феодорита: храм, присвячений Твоєму імені, буде для мене замість неба; у ньому я поклонятимуся Тобі й приноситиму подячне славослів'я, бачачи Твоє людинолюбство до мене й правду щодо ворогів; бо оскільки вони чинили мені зло, то Ти за Своєю істиною постановив погубити їх, а мене за Своєю милістю спас.","Прим.: Золотоустого: тобто дякуватиму Тобі не тільки за благодіяння, а й за саму невимовну славу, безкінечну велич і невимовне єство; бо немає жодної частини творіння, ні горньої, ні дольньої, що не подавала б голосу, гучніше за сурму звіщаючи про велич Твого імені. Феодорита: у всьому, каже, дорогоцінне ім'я Твоє, і всі, хто бачив Твою силу, оспівують його."],"h":"Поклонюся до храму святого Твого й прославлю ім'я Твоє за милість Твою й істину Твою, бо Ти звеличив понад усе святе ім'я Твоє"},{"v":"3","t":["Те саме сказав у 101-му псалмі. Ти, каже, Господи, сподобиш мене великого піклування про душу, бо Ти й сильний це звершити. Або: Твоєю силою Ти дуже піднесеш мою душу, інакше — звеличиш мою душу й поставиш її, за Золотоустим, вище за скорботи. Той самий Давид сказав і в 11-му псалмі: за висотою Твоєю примножив Ти піклування про синів людських.","Прим.: За іншим тлумачем, дієслово «примножиш» поставлене замість «збережеш мене надовго» і Твоєю силою з тління приведеш до нетління. Феодорита: тобто Твоєю силою звеличиш мою душу й сповниш її бадьорістю й сміливістю."],"h":"У той день, коли покличу Тебе, швидко вислухай мене; примножиш силу в душі моїй"},{"v":"4","t":["Усі, веде далі, царі землі, тобто благочестиві й ті, хто увірував, дякуватимуть Тобі, Господи. За що? За те, відповідає, що почули слова уст Твоїх, тобто слова закону, пророків, євангельські й апостольські. Бо й самі царі зобов'язані дякувати не стільки за інші Його благодіяння, скільки за те, що почули й пізнали слова Твоїх Писань, бо з цих Твоїх слів походить благочестя й доброчесне життя, а це справжнє й велике благодіяння для душі.","Прим.: Феодорита: і тоді всі, дізнавшись про ту найбільшу перемогу (тобто над сусідніми народами), дивувалися силі Бога всіх. Але особливо після вочоловічення Бога й Спаса нашого і царі, і начальники прославляють Творця всіх. І щодо першої перемоги не чули слів, а бачили славне діло; а нині й слова чують і користуються євангельськими мовами. Золотоустого: бо й царство не може дати їм такої користі, яку дає слухання Твоїх слів: це їхня безпека, це сила, це краса, це окраса й міць начальства. А в Золотоустого й Феодорита пишеться так: нехай заспівають на дорогах Господніх, тобто в законах, у повеліннях Господніх. А в Аполлінарія в героїчних віршах пишеться «в піснях» так: богонатхненними піснями заспівають Богові. Також в одній примітці написано: написав пісні Богові, якими велить співати всім з язичників."],"h":"Нехай прославлять Тебе, Господи, усі царі землі, бо почули всі слова уст Твоїх"},{"v":"5","t":["Усі, каже, благочестиві царі співатимуть Тобі, Господи, піснями, складеними для Тебе: бо пісні Господні — пісні, складені Мойсеєм і Давидом. Утім, піснями можуть бути й просто славослів'я Бога. Чому ж вони співатимуть ці пісні? Бо слава Твоя, Господи, тобто поняття й думка про Тебе, — велика; бо всі люди уявляють Тебе великим, тобто ті, хто відчуває Твої благодіяння. Або: велика слава Господня, тобто, за словами Золотоустого, явна для всіх, бо небо й земля сповнені Його слави; адже всі загалом — і ангели, і люди — прославляють Його.","Прим.: Золотоустого: якщо читати «на дорогах Господніх», то значення цих слів таке: нехай читають у законах Твоїх; а якщо «в піснях Твоїх», то таке: нехай співають, каже, нехай проповідують про Твої великі діла; бо це означає «нехай заспівають». Феодорита: усі, каже, дивуватимуться Божому промислу й домобудівництву; бо дорогами називає розпорядження."],"h":"І нехай заспівають на дорогах Господніх, бо велика слава Господня"},{"v":"6","t":["Ці слова подібні до таких: що живе на висотах і дивиться на смиренне (що написано в 112-му псалмі). Або: Бог, хоча за природою високий, але дивиться, тобто споглядає й на смиренне, бо Він промишляє й про землю, поширюючи Своє піклування навіть на найменші й нікчемні творіння. Або: дивиться, тобто береже смиренномудрих. Смиренних, каже, тобто земних і марних дій, як негідних Божої висоти, Бог і зблизька не терпить і не бачить, як і Сам каже: не знаю вас (Мт. 25:12). А високі дії, тобто небесні, як гідні Божого погляду, Бог і здалека знає, як сказано: знає Господь дорогу праведних (Пс. 1:6). А Боже знання й здалека означає, що Він дуже вдоволений. Або тут слово, за Золотоустим, про передбачення, тобто що Бог здалека й ще до існування чогось знає все, як мовила й цнотлива Сусанна: що знаєш усе до його буття (Дан. 13:42).","Прим.: Інший каже: або, можливо, так: і якщо хтось серед людей і пихатий серцем, то й такий не сховається від Бога; тому й в Акили сказано: і високого здалека знає. Феодорита: знає все до буття й, бачачи здалека сильних, кожному дає відповідні ліки. А інші вважають, що Бог дивиться на смиренних, тобто промишляє й усіляко піклується та допомагає, бувши вдоволеним їхнім смиренням, а пихатих і гордих знає тільки здалека, не допомагаючи їм і не заступаючись за них, бо ненавидить їхню гордість."],"h":"Бо високий Господь і на смиренного дивиться, а високе здалека пізнає"},{"v":"7","t":["Прим.: Феодорита: рукою називає покарання, а правицею — благодіяння; бо ворогів Ти покарав, а мене спас."],"h":"Якщо піду посеред скорботи, Ти оживиш мене; на гнів ворогів моїх простягнув Ти руку Твою, і спасла мене правиця Твоя"},{"v":"8","t":["Тобто Господь помститься за мене, як і апостол каже: Мені помста, Я віддам, говорить Господь (Рим. 12:19).","Прим.: Феодорита: Господь, що вочоловічився, сплатить за мене мій борг; бо Він знищив рукописання, що було проти нас, і прибив його до хреста.","«Господи, милість Твоя повік»","Це подібне до сказаного в 135-му псалмі: бо повік милість Його.","«Діл рук Твоїх не зневаж»","Ти, каже, милостивий і Творець; тому не зневаж нас, створених Тобою.","Прим.: Золотоустого: щоб ми, почувши про милість, не впадали в безтурботність, треба й нам самим чинити щось гідне милості, бо Він каже: кого помилую, помилую (Рим. 9:15)."],"h":"Господь віддасть за мене"}],"138":[{"v":"0","t":["Псалом Давидів","Прим.: В інших списках напис на цьому псалмі такий: на кінець, псалом Давидів, Захарії, у розсіянні. Феодорита: цього напису немає ні в єврейському тексті, ні в Сімдесятьох, ні в інших тлумачів; але хтось самовільно, за своїм розумінням цього псалма, додав цей напис. Цей псалом містить пророцтво про царя Йосію, який покарав ідольських жерців, а тим, хто любив благочестя, віддав велику честь. Тут він показаний таким, що дивується Божому передбаченню про нього: бо коли Єровоам приносив жертви телицям, Бог тоді ж провістив йому, що постане син Давидів на ім'я Йосія, і віддасть ідольських жерців на смерть, і спалить їхні кості. А на думку інших, цей псалом стосується особи Захарії, коли сини Ізраїлеві ще були в полоні й сам пророк Захарія з ними. Він же означає й покликання народів і спротив Христові Спасителю з боку ізраїльського народу, тому й наприкінці написано вказівку на час Його пришестя."]},{"v":"1","t":["Господи, так починає, Ти випробував мене досвідом і через спокусу, не тому, що Ти не знав мене до цього випробування; бо як міг не знати мене Ти, що знаєш усе до буття всього: що знаєш, за словами Сусанни, усе до його буття (Дан. 13:42)? Але Ти випробував мене спокусами для того, щоб я став відомим і випробуваним і для тих, хто не знав мене, і так був для них прикладом мужності й терпіння. Ти ж, Господи, достеменно знав мене, який я є. Або каже, що Ти випробував і пізнав мене в тому значенні, що Ти добре знаєш мене; тому й апостол, кажучи, що Бог випробовує серця (Рим. 8:27), показує цим не те, що Бог до випробування не знає сердець, — ні, не те, — а цим випробуванням дає поняття про чисте, ясне й точне Боже знання.","Прим.: Золотоустого: що ти кажеш: Бог пізнав після випробування? а до випробування не знав? ні, зовсім не так, але вираз «Ти випробував» означає найясніше знання, тобто Ти достеменно знаєш мене. Василія Великого: спокуси бувають двох родів: або скорботи випробовують серця, як золото в горнилі, виявляючи їхню чистоту через терпіння, або часто й саме благополуччя в житті для багатьох буває замість спокуси. Бо однаково важко й зберегти свою душу від приниження в скрутних обставинах, і не піднестися надміру в блискучому житті. Феодорита: випробуванням для чеснот є не тільки бідність і печаль, а й царство й благополуччя; і як у сумних обставинах нас випробовують, чи можемо мужньо переносити те, що трапилося, так і благополуччям нас випробовують, і ми виявляємося або пихатими через щастя, або такими, що знають, якої воно природи.","«Ти пізнав сидіння моє і вставання моє»","Ти, веде далі, Господи, пізнав мене і коли я сідаю, і коли встаю, тобто знав усе моє життя, яке, за словами Феодорита, полягає в цих двох станах — у спокої й русі, у заняттях і бездіяльності, у відпочинку й дії.","Прим.: Євсевія: хто пам'ятає слово, де сказано: і повчатимешся в Божих словах, сидячи вдома й ідучи дорогою, лягаючи й встаючи, — і поводиться гідно Божого знання і під час сидіння, і під час вставання, той може сказати ці слова: Ти пізнав сидіння моє і вставання моє. А у вищому значенні сидіння — це така мужність розумної душі, за якої вона буває непорушна до зла; її вставання — перехід від чуттєвих предметів до мисленних; тож і це сидіння тих, хто має прекрасну твердість, і це вставання тих, хто прекрасно встає до дій, тобто і спокій, і ревна дія стають відомі Богові. Феодорита: це слова чистої душі й здорового сумління."],"h":"Господи, Ти випробував мене і пізнав мене"},{"v":"2","t":["Оскільки вище сказав: Господи, Ти випробував мене й пізнав мене, то щоб хтось не робив із цього висновку, що Бог знає людей тільки тоді, коли випробує їх, тут царепророк пояснює сказане ним і каже, що коли Бог знає сердечні думки людей до їхнього руху в серці, а краще — за багато років і родів наперед (бо це означає «здалека»), то яка Йому потреба у випробуванні, щоб пізнати? бо це зовсім недоладно.","Прим.: Євсевія: справді одному Богові властиво випробовувати людські таємниці."],"h":"Ти зрозумів думки мої здалека"},{"v":"3","t":["Ти, каже, Господи, випробував усі стежки й міри мого життя і дуже добре знаєш, скільки воно йде вперед і скільки ще лишається позаду; бо мотузка (так у грецькому) була мірою землі в єгиптян і персів: що в нас (у греків) стадія (поприще), те в них була (так звана землемірна) мотузка. Дієслова ж «Ти випробував» і «дослідив» щодо Бога означають непогрішне Боже знання. І не тільки Ти, Господи, знаєш моє життя, а й усі діла, як добрі, так і погані. Далі не сказав «Ти бачив», а «передбачив» і передпізнав їх, перш ніж вони були вчинені.","Прим.: А оскільки стадію становлять сто двадцять п'ять стоп, то й мотузка завдовжки мала таку саму кількість; і як вісім стадій становлять одну милю, так і вісім мотузок становлять теж милю.","Прим.: За словами Феодорита, дорогою й стежкою називає діла, а мірою (мотузкою) — їхню правоту, за подобою, взятою від будівничих, що вирівнюють стіни схилом, або мотузкою."],"h":"Стежку мою і міру мою Ти дослідив, і всі дороги мої передбачив"},{"v":"4-5","t":["Ти, Господи, веде далі, пізнав між іншим і те, що немає злого наміру в моїх словах, ні лукавства й кривизни. Потім говорить загальне: Ти, Господи, знаєш усе наступне, чи майбутнє, і все колишнє, чи минуле, тобто Ти знаєш це все водночас і ніщо не може сховатися від Твого знання; і Ти не тільки створив мене, а й по створенні тримаєш і покриваєш мене, так що вираз «Ти створив» означає Божу творчість, а «поклав на мене руку Твою» означає Божий промисел.","Прим.: Слова Орігена: зауваж, чому про середнє (між наступним і колишнім) промовчано; очевидно тому, що зло перебуває посередині, якого немає ні на початку, ні наприкінці сущого і якого Бог не знає, як сказано: не знаю вас, — тобто тим знанням, що стосується засвоєння.","Прим.: Золотоустого: від сили передбачення перейшов до творчої сили й знову від творчої — до сили промислу. Про це свідчить і Павло щодо Христа, коли каже, що Ним створено все (Кол. 1:16), а це означає творчість; потім, указуючи на дію промислу, каже: і все Ним стоїть (17); знову, виражаючи творчість, каже: через Якого й віки сотворив (Євр. 1:2). Він же показує й промисел словами: тримаючи все словом сили Своєї (ст. 3); бо ми потребуємо Його сили не тільки для появи нашої на світ, а й для нашого існування й перебування. Євсевій: або слова «Ти поклав руку Твою на мене» поставлено замість «Ти дав мені Своє благословення, і зробив мене начальником, і сповнив божественної сили»; адже те саме, як ми віруємо, передається через покладання рук тим, кого рукопокладають; і при немовляті в утробі так само перебуває рука Божа, не тільки виводячи його, коли воно народжується, а й оживлюючи й зберігаючи його."],"h":"Бо немає підступу на язиці моєму: ось, Господи, Ти пізнав усе останнє й давнє; Ти створив мене і поклав на мене руку Твою"},{"v":"6","t":["Знання, веде далі, Тебе, Господи, тобто моє пізнання Тебе вище за мене, як пояснює дехто, тобто воно перевершує моє розуміння й осягнення; і, показуючи це ясніше, каже: Твоє знання сильніше за обсяг мого розуму й міркування, і я знесилююся щодо цього пізнання, щоб міг умістити його в своєму розумі. А під цим знанням, за словами Золотоустого, розуміє знання природи й єства Божого; адже ми розуміємо тільки буття Бога, а що Бог за Своїм єством, того не розуміємо; так само знаємо, що Бог усюдисущий, а як Він усюдисущий, того не знаємо; знаємо також, що Він благий, і людинолюбний, і премудрий, і всесильний, і має інші подібні властивості, а наскільки Він благий і премудрий, не знаємо. З цими словами згідне й те, що говорить про премудрість, тобто про Бога, Екклезіаст: я сказав: стану мудрим, а вона (мудрість) віддалилася від мене, я став далі від неї, ніж був (раніше); глибина глибока, хто знайде її дно? (Екл. 7:24-25); і Павло говорить подібне: о глибино багатства, і премудрості, і пізнання Божого! які незбагненні присуди Його і недосліджені дороги Його! (Рим. 11:33).","Дехто ж разом з божественним Золотоустим розуміли це інакше: дивна премудрість Твоя виявилася в створенні й улаштуванні мене, я знесилююся перед нею, щоб міг гідно оспівати й прославити її. Але скаже хтось: якщо ти, Давиде, не знаєш достеменно, що це за премудрість, то як же дивуєшся їй? На це відповідає: саме тому я й дивуюся Божій премудрості, що вона незбагненна, так само як і ми, хоча й не можемо збагнути, що таке промінь і світло сонця, проте саме через те, що не збагнемо його, особливо дивуємося йому. Потім він дивується й іншій Божій силі, тобто тому, що Бог Своєю могутністю й промислом усюдисущий, сповнює кожне місце й, як пояснює Золотоустий, перебуває вище за все.","Прим.: Григорія Богослова: великий Давид, якому Бог явив Свою невідому й таємну премудрість, ясно визнає незбагненність знання (Його), то називаючи Божі суди безоднею великою, основи якої не можна досягти ні мірою, ні чуттям, то кажучи, що дивним виявилося знання (Його) над ним і над його складом і що воно сильніше за його силу й обсяг. Бо якщо, каже, залишивши все інше, я звернуся до самого себе й почну розглядати всю людську природу та її устрій, то мимоволі мушу сказати: що це за змішання в нас? Що за рух? Як безсмертне з'єднане зі смертним? Як я ллюся додолу й підношуся вгору? Як одна й та сама жива істота смертна й безсмертна? І що за таємниця в моїй природі? Як я вимірююся місцем, а розум не обмежується ним, але, залишаючись в одному й тому самому місці, обходить усе? Як безтілесне міститься в крові й диханні?"],"h":"Дивне знання Твоє наді мною; воно сильне, я не можу збагнути його"},{"v":"7-8","t":["Духом Божим Давид іносказально називає Духа Святого, а лицем Божим — Сина, як образ Отця і відбиток Його єства; бо той, хто бачив, каже, Мене, бачив Отця (Ін. 14:9). Ім'ям неба Давид указує на найвище й перше небо, сотворене на початку, а адом виражає найглибше в землі місце. Після цього згадує й про безодню та дно моря; цими частинами світу Давид виразив і кожне недоступне й непрохідне для людей місце.","Прим.: Золотоустого: бачиш, який вдячний раб? Дякую, каже, Тобі за те, що Ти — мій Владика незбагненний. І він розуміє тут не єство, бо воно, без сумніву, незбагненне, тож це пропускає. А говорить про Божу всюдисущість через Його силу й промисел і про сповнення кожного місця; і показує, що й те для нього незбагненне, як Він усюдисущий. Кирила: Ти все сповнюєш; Ти присутній при всьому не частково, а при всьому загалом водночас. Далі, показавши, що сила Духа проникає все, каже: куди піду від Духа Твого? Тут піснеспівець не міг би сказати про Духа, що Він Своєю появою проходить усе, якби Він був рабом чи твориною; до того ж називає Його лицем і рукою Божою. Тож хто не бачить божественної слави цього Духа, чуючи слова: куди піду від Духа Твого? Євсевія: якщо станеться зі мною гріх і через це буде потреба втекти чи віддалитися, то куди мені піти, щоб утекти? І де мені бути, коли Ти, Боже, тримаєш усе? Григорія Богослова: тож страшне це сповнення всього, бо Божої сили не можна уникнути ніде, хоч би хтось злетів на небо, хоч би оселився в аді, хоч би втік на схід, хоч би сховався в глибинах моря. Не сказав, каже Золотоустий: куди б я не пішов, Ти всюди йдеш за мною, — а: куди б не пішов, Ти там; там, каже, я Тебе вже застаю. Григорій Ніський вважає, що чотирма частинами світу — висотою, межа якої небо, глибиною, кінець якої ад, ранком, тобто сходом, і краями моря, тобто заходом, — зображено чотири кінці чесного хреста: небом і адом позначено верхню й нижню частини хреста, а сходом і заходом указано на дві його поперечні частини, як їх же виражено й висотою, глибиною, довжиною та шириною, про які згадує Павло в посланні до ефесян (Еф. 3:18). Феодорита: треба зауважити, що за цим ученням і Бог, і пресвятий Дух мають одну дію: куди піду від Духа Твого, і від лиця Твого куди втечу? А в яких осіб одна дія, у тих, без сумніву, і одна сила; а в кого одна сила, у тих і одне єство. Отже, у Бога й Духа одне єство. Добре також із небом поєднав вираз «Ти там», а з адом — «Ти присутній»; бо на небі Він спочиває в ангелах, що живуть там, а всюди й при всьому Він присутній і перебуває; і в Ньому, за словами божественного апостола, ми живемо, і рухаємося, і існуємо."],"h":"Куди піду від Духа Твого? і від лиця Твого куди втечу? Якщо зійду на небо, Ти там; якщо зійду в ад, Ти там"},{"v":"9-10","t":["Крила в Давида — це діяльна сила його розуму: якщо, каже, я на цих крилах у мріях свого розуму полину в морську безодню, сподіваючись, чи не сховаюся там від Тебе, Господи, то й там однак Твоя божественна сила вкаже мені дорогу й знову втримає мене, тобто навіть у безодню я не можу піти без Твоєї сили; вона випередить мене, вона дасть мені місце для притулку, і вона ж знову неминуче втримає. А сказавши «вранці», цим позначає той час, коли розум людини особливо тверезий.","Частку «бо» тут сказано зайво. Дехто ж під ранком розумів схід, а під краями моря — захід. Тож якщо, каже, на крилах свого розуму полину на схід, то сила Твоя поведе мене, як того, хто літає розумом; і вона ж утримає, якщо дійду до заходу.","Прим.: Феодорита: тут відкриває неописаність Божого єства. І пророк Йона так само зазнав цієї сили: бо, наважившись утекти від Бога всіх, він був упійманий і зв'язаний хвилями, і вкинутий у кита, наче в темницю, і поведений у те місто, куди був посланий (раніше); і справдилося сказане: якщо оселюся й у безоднях моря, то й там рука Твоя вкаже мені дорогу й утримає мене правиця Твоя. А ці слова подібні до слів Амоса: не втече від них утікач і не вціліє від них той, хто намагається вціліти. Якщо сховаються й в аді, то й звідти рука Моя вирве їх. І якщо зійдуть на небо, то й звідти скину їх. Якщо сховаються на вершині Кармілу, то й там пошукаю й звідти візьму їх. І якщо зануряться від очей Моїх у морські глибини, то й там накажу змієві, і він покусає їх (Ам. 9:1-3)."],"h":"Якщо візьму крила мої вранці й оселюся на краях моря, то й там рука Твоя поведе мене, і втримає мене правиця Твоя"},{"v":"11","t":["Я, веде далі, міркував і сказав у собі, що нарешті зможу сховатися в темряві й що ніч затопче мене, тобто сховає мене; бо хто топче поверхню землі, той покриває її своїми ногами; однак, визнає, потім я пізнав, що й сама ніч і темрява світла в солодкості моїй, тобто перед Богом, бо солодкістю своєю він називає Бога, адже й саму згадку про Бога він називав веселощами: згадав я, каже, Бога й звеселився (Пс. 76:4); з цього я дізнався, що й сама темрява не може сховати мене від Бога.","Прим.: Григорій Богослов (слово 40-ве), пояснюючи слова «ніч — світло в солодкості моїй», каже: як мені відомий двоякий вогонь, так є й двояке світло. Одне — світильник розуму, і воно спрямовує наші богоугодні стопи. А друге оманливе, допитливе, протилежне істинному світлу й видає себе за істинне світло, щоб звабити зовнішністю. Це темрява, і її вважають просвітленням ті, кого розтлило сластолюбство. Бо що каже Давид? Ніч була довкола мене, нещасного, і я не знав, бо просвітленням вважав насолоду, тобто під час моєї насолоди ніч сластолюбства, що затьмарює розум, здавалася мені, розтлінному насолодою, просвітленням. А Оріген вважає, що «ἄρα» (отже) тут ужито замість «утім»."],"h":"І сказав я: чи темрява затопче мене? а ніч — світло в солодкості моїй"},{"v":"12","t":["У Тебе, каже, Господи, темрява не буде темною; бо вираз «від Тебе» (у грецькому) інший перекладач замінив виразом «у Тебе»; адже наша темрява в Тебе не темрява, бо й вона світить, і навіть ніч у Тебе світла, як день; і як світле денне світло, так світла в Тебе нічна темрява, тобто й те, й інше в Тебе рівні й однаково світлі. Давид говорить це, щоб показати, що перед Богом усе відкрите. Але можна розуміти ці слова й в іншому значенні, за Золотоустим: я, каже, оточений темрявою спокус і скорбот, сказав у собі: невже заволодіє мною ця темрява? потім, щойно Ти, Господи, захотів, ніч печалі й скорботи відразу обернулася для мене на світло радості й веселощів. Згідно з цим маємо пояснювати й інші слова. А Григорій Богослов пояснив це інакше: коли, каже, я насолоджувався й віддавався розкошам, ніч цього сластолюбства, що затьмарювала мій розум, здавалася мені світлом; бо й ніч, і темрява були довкола мене, окаянного, і я не знав цього, бо думав, що моя насолода — просвітлення.","Прим.: Золотоустого: бо коли буде завгодно Богові, то й природа стихій зміниться на протилежне, і так само на протилежне, як на своє, наче від самого початку таку властивість їй дано. Бо якщо Тобі буде завгодно, то така буде ніч, і так само дано буде їй світло, як дано темряву. Феодорита: ця темрява — темрява для мене, бо в мене є різниця між світлом і темрявою. А для Тебе, мисленного Світла, і ніч подібна до найсвітлішого дня й світліша за всяке полуденне світло. Тому хто грішить у темряві й каже, за словами Никити, те, що сказано в Сираха: хто бачить мене? Темрява довкола мене, і стіни ховають, і ніхто не бачить мене; чого мені боятися? Моїх гріхів Всевишній не згадає (Сир. 23:25), — той безчутний. Бо Сам каже в Єремії: Я Бог близький, а не Бог далекий. І ще: чи зробить щось людина таємно, а Я не побачу? хіба не Я наповнюю небо й землю? говорить Господь (Єр. 23:23-24)."],"h":"Бо темрява не буде темною в Тебе, і ніч засвітиться, як день; яка її темрява, таке й її світло"},{"v":"13","t":["Золотоустий каже, що Давид під нутром розуміє всього себе, частиною виражаючи ціле. Ти, каже, Господи, набув мене й зробив Своєю власністю, удостоюючи Свого промислу й піклування, адже хто набуває щось, той і дбає про набуте.","Прим.: Слова Григорія Богослова: якщо ж, як пояснюють дехто, нутро (нирки) — образ пожадливої сили, то до Тебе, каже, спрямую своє бажання, а не до чогось іншого, ворожого й небезпечного. Божественного Кирила: і нирки можуть бути образом внутрішньої дії сили розрізнення в розумі, за якою треба відкидати те, що звичайно завдає шкоди, і вважати бажаним і гідним набуття все корисне, згідно з цією заповіддю: усе випробовуйте, доброго тримайтеся, від усякого виду зла утримуйтеся. Тож оскільки нирки — частини, здатні здійснювати відділення в тілі, бо дуже добре вони виводять зайве, а придатне й корисне вносять у природу, то пристойно розуміти нирки як розрізнення розуму. Тому нирки святих священні й становлять дар Богові, тобто розрізнення в розумі, яке вони мають. Бо віддані Богові подібні до міняйлів і скупих, які ніколи не приймають підробленої монети, а дуже точно оцінюють ту, що може принести вигоду. Никити: це може сказати (тобто слова «Ти набув нутро моє») і той, хто веде безшлюбне життя й віддав своє нутро (нирки) Богові. Божественного Григорія Солунського: Ти зробив Своїм набутком нирки мої — не тільки, каже, зробив Своєю всю пожадливу силу моєї душі, а й те, що розпалює полум'я цього бажання в тілі, звернувшись до тієї, що носить його (мабуть, до душі), через неї злітає до Тебе, до Тебе прив'язується й до Тебе прилипає; бо як у тих, хто пристрасний до чуттєвих і тлінних насолод, усе душевне бажання виливається в плоть, тому й вони цілком стають плоттю, і Дух Божий не може перебувати в них, так і в тих, хто підносить свій розум до Бога й прив'язав свою душу до божественної любові, і плоть перетворюється, певним чином підноситься разом із ними й насолоджується з ними божественним спілкуванням, стаючи й сама набутком і житлом Божим, уже не маючи в собі прихованої в ній ворожнечі проти Бога й не пожадаючи проти Духа (Добротолюбіє, грецьке видання, с. 960).","«Ти прийняв мене з утроби матері моєї»","Господи, сказав Давид у 70-му псалмі, від утроби матері моєї Ти мій покровитель, тобто від самих пелюшок і від найпершого віку Ти, Господи, покривав мене."],"h":"Бо Ти набув нутро моє"},{"v":"14","t":["Ми дивуємося багатьом речам, але не зі страхом; наприклад, дивуємося красі й величині тіл і будівель, хитрощам і мистецтвам тощо, але не страхаємося. А коли трапиться схилитися над глибиною моря, тоді ми не просто дивуємося, а й зі страхом. Так і пророк Давид, зазирнувши в неосяжну причину й безмірну глибину Божої сили й мудрості та Його різноманітного устрою і вражений, здивувався зі страхом і трепетом тій незбагненності й безмірності; і так, звернувшись до своєї нікчемності, міг вигукнути тільки цими словами: дякую Тобі, Господи!","«Дивні діла Твої, і душа моя дуже добре знає це»","Дивні, вигукує, усі діла Твої, Господи; тому й душа моя дуже добре знає, що вони воістину дивні й гідні всякого подиву й захоплення.","Прим.: Золотоустого: що говорити про Тебе, коли й творіння Твої містять у собі багато дивного! Але скажи, пророче: якщо дивним стало пізнання Його, якщо воно таке сильне, що ти знесилюєшся перед ним, то як знову кажеш: душа моя дуже добре знає це? Так; але те сказано про Нього, а це — про Його діла. А якщо й це про Нього, то можемо сказати, що він знає, що Бог дивний, що Він великий, що високий, але що Він таке за єством і яка Його велич, цього не знає. І це незнання — доказ знання. Так ми не знаємо й моря, таке воно велике, проте саме тому ми й добре знаємо. А якщо хтось скаже, що знає його величину, то саме той і не знає його. Тому визнання в нерозумінні — доказ знання, а свідчення про розуміння — незнання."],"h":"Прославлю Тебе, бо страшно Ти став дивним"},{"v":"15","t":["Тобі, веде далі, Господи, відома й сама будова моїх костей, покритих від Тебе, при їхньому творенні, плоттю, щоб не були видні. Або можна розуміти й інакше. Кість чоловіка — дружина, бо вона була одним із ребер Адама. Отже, дружина, каже, яку Ти, Господи, узяв із ребра Адама таємно, тобто навівши на Адама сон-заціпеніння, ця, кажу, дружина не сховалася від Тебе під час куштування плоду з дерева пізнання в раю, за поясненням Ісидора Пелусіота.","Прим.: Ісидор каже, що Давид промовив це від особи Адама: не сховалася кість моя від Тебе, тобто не сховалося від Тебе падіння моєї дружини, яку Ти створив таємно з моїх костей, приспавши мене глибоким сном. Зауваж при цьому, що ці слова Давида подібні до слів Екклезіаста: як кості в утробі вагітної, так не збагне людина всіх Божих діл, які Він сотворить (Екл. 11:5). Тому й Акила переклав: не сховалися кості мої від Тебе, створені Тобою таємно, що, за поясненням Феодорита, означає таке: ніщо, каже, не може сховатися від Тебе, що влаштував людське єство в таємній мистецькій світлиці природи.","«І склад мій у глибинах землі»","Тобі, каже, Господи, відоме єство мого тіла, що ховається в глибині землі й знову розпадається по смерті, тобто Ти, Господи, бачиш мене і тоді, коли я ущільнююся й складаюся в лоні моєї матері, і так само, коли розпадаюся в гробі й в утробі землі. Або можна розуміти й інакше: Тобі, Господи, відомий мій склад і устрій, що виткався й утворився в нутрі материнської утроби, наче в далеких і таємних місцях землі.","Прим.: Я склався, або, за іншим тлумачем, утворився, ніби в глибинах землі. До цього можна прикласти й такі слова Золотоустого: усі кажуть одне й те саме, що, старанно створивши мене, Ти достеменно знаєш мене, знаєш і кожен член, і вік; тому й Христос казав: у вас же й волосся на голові все пораховане. Інший (тобто Никита) каже, що ті, хто досліджував природу тварин, кажуть, що незбагненна зміна крові на кістку, хоч би інші плоті й нерви, якого б роду не були, хоч би як їх розуміли. Але Тобі (лише), каже, відомий склад моїх костей."],"h":"Не сховалася кість моя від Тебе, яку Ти створив таємно"},{"v":"16","t":["Неоформленим (необробленим) Давид тут називає або неутворене й недосконале людське немовля, що ще не дістало в таємній мистецькій світлиці природи, тобто в жіночому лоні, належного устрою, або так називає недосконалий рух розуму. Ти, каже, Господи, знав мене, перш ніж я утворився в утробі моєї матері; і понад це Ти знаєш думки й рухи мого розуму, перш ніж вони набули повного вигляду; бо Ти знаєш усе, за словами Сусанни, до буття всього.","«І в книзі Твоїй усі будуть записані»","Книгою Божою названо точне Боже знання, а Божим записом, за словами Золотоустого, — постійну й непогрішну пам'ять. Отже, у книгу загального Божого знання вписуються, каже, усі загалом, і праведні, і грішні, а в книгу близького Божого знання вписуються тільки праведники.","Прим.: Слова Григорія Богослова: є якась книга життя, у яку вписуються всі, хто очистився від першого народження, що є таємницею ночі, денним і світлим новотворенням, за яким кожен окремо дістає відмінний і найчистіший устрій, що в Давида пристойно названий денним і протилежним нічному. І такі всі дні свого життя провели так стрійно, що жоден із них не має в собі нічого недоладного. Або, за здогадом святого Єпифанія, божественний Давид уподібнює книзі лоно, у якому творяться й утворюються немовлята. Отже, і те, каже, що не набуло образу в утробі, бачили очі Твої. А Варин щодо слова βύβλιον каже: βύβλιον відрізняється від βιβλίον: першим (βύβλιον) називають неписану книгу (таку назву дав антіохійський архієрей від рослини біля міста Вавла), як у такому місці: у книзі (βυβλίῳ) Твоїй усі будуть записані, а другим (βιβλίον) — писану. Утім, щодо слова βιβλίον він же вважає, що його пишуть без різниці й воно означає одне й те саме, і в аттиків пишеться через υ, а в іонійців через ι.","«За днів будуть створені, і ніхто з них»","Віруючі, веде далі, християни будуть створені світлом і дією Святого Духа на творіння відмінне й найчистіше, протилежне творінню тілесному, нічному й пристрасному, тобто відродяться духовно через святе хрещення; саме вони й записуються в Божу книгу, і немає жодного з тих, хто відроджується хрещенням і вписується в цю книгу, хто не присвоював би себе духовно й не спрямовувався до чесноти. Ми пояснили це, як могли, спираючись на слова Григорія Богослова. А Золотоустий, називаючи це місце неясним і темним, подає тільки думку, за перекладом іншого тлумача, таку: ще неутвореного й недосконалого бачили мене очі Твої, Господи, і бачили так точно, як бачать тих, хто записаний у Твоїй книзі, тобто як бачать у свій час і цілком утворених, що не потребують жодної повноти досконалості більше для свого складу.","Прим.: Ясніше ж це в Золотоустого: очі Твої бачили мене так ясно ще до мого створення й утворення, як бачили його, що вже досяг повноти й не потребував уже жодного дня для досконалості й повноти складу, ніби він відразу по своєму народженні став досконалим за віком і записаним у Твоїх книгах, тобто в Твоєму знанні й твердій пам'яті. А щоб ти знав, що це правда, то вислухай пояснення іншого: ще неутвореного бачили мене очі Твої разом з усіма записаними в Твоїй книзі, що творяться вдень, яким немає потреби в жодному (тобто дні). Майже таке саме й Феодоритове пояснення цих слів, у якому додано ще, що під книгою треба розуміти всеосяжне (Боже) знання й Божу пам'ять, що нічого не забуває. Безіменного: жодного змішання не буде в той день суду між створеними: бо ні грішник не знайдеться серед праведників, ні праведник серед грішників, а за непогрішним знанням усіх Бог розділить кожному своє, як належить."],"h":"Неоформлене моє бачили очі Твої"},{"v":"17","t":["Друзі Божі — це всі ті, хто наблизився до Бога через чесноту й виконання Божих заповідей: ви друзі Мої, каже, якщо виконуєте те, що Я заповідаю вам (Ін. 15:14). А серед чеснот, за Золотоустим, не маловажна й шана до друзів Божих. Замість «володарювання їхні» інший переклав «племена їхні», що без іносказання означає: вони. Міцними, каже, і сильними в чесноті й непохитними до зла стали друзі Божі. Або під володарюваннями розумій владу, яку дістав кожен друг Божий над нечистими духами; цими словами Давид неясно вказує на божественних апостолів або на тих, хто доброчесний і наслідує божественних апостолів.","Прим.: Тому й Ісидор Пелусіот пише: і ти, якщо хочеш бути другом Божим, володарюй сильно, віддаючи справедливість не за дари чи дружбу, а за гідністю; такими словами святий виражає тут начальство й владу. Григорій Солунський під володарюваннями розумів начальників і перших святих у кожному чині, як-от у чині апостолів — первоверховних Петра й Павла або й дванадцятьох, серед мучеників — Димитрія, Георгія й Феодорів, серед преподобних — Антонія, Саву й Євфимія тощо. Інший: розумієш слова «дуже утвердилися володарювання їхні» як «дуже багато їх у мене було»; тому й далі каже: перелічу їх, і піску перевищать числом. Феодорит: це треба відносити до царя Йосії, який, за оповіддю, удостоїв священників усякої честі, бо він, без сумніву, чув обітниці, дані Богом Авраамові цими словами: благословлю тих, хто благословляє тебе. Слова Кирила: хто може з плодів пізнавати друзів Божих, той дуже вшанує їх, бо й начальства їхні, тобто їхні думки про їхнє начальство, дуже тверді. Безіменного: Ти промишляв, каже, про мене й провів мене, а я на віддяку за це шаную друзів Твоїх. Феодотіона: дуже зміцніли убогі їхні, що Феодорит пояснює так: бо ті, хто через беззаконня нечестивих царів жив у бідності й убогості, за Йосії удостоїлися великої честі."],"h":"А для мене дуже шановні стали друзі Твої, Боже, дуже утвердилися володарювання їхні"},{"v":"18","t":["Це сказано з особливою силою: спробую, каже, перелічити друзів Божих — і їх виявиться безліч, бо їх знайдеться більше, ніж піску морського. Але в Бога пораховані не тільки вони, а й волосся на їхній голові.","Прим.: Золотоустого: я їх шаную; але Ти часто примножуєш їх понад пісок, і не тільки примножуєш, а й зміцнюєш; бо вираз «утвердилися» має таке значення. І показуєш подвійне благополуччя, що полягає і в численності, і в надмірі сили. Феодорита: бо через благочестя Йосії й ті, що раніше були нечестиві, просвітилися розумом, забажали повернення й полюбили життя згідне з законом, і ті, кого було мало, стали незліченні. Це ж слово провіщає й ту зміну всесвіту, що настала після вочоловічення Бога й Спаса нашого; бо ревних богошанувальників у кожному місті, у кожній країні незліченно.","«Я встав, і ще я з Тобою»","Я, додає, устав, тобто звільнився від зол і спокус, через які я став наче мертвий; але, і звільнившись, я не забув милості й благодіянь, явлених мені Тобою, Господи, як роблять навпаки багато хто, хто в щасті забуває про своє колишнє нещастя; а завжди пам'ятаю і спокуси, і благодіяння, тому й завжди дякую Тобі, виконуючи Твої заповіді й усяку чесноту.","Прим.: Золотоустого: немаловажна й ця ознака чесноти, коли хтось і в благополуччі зберігає чесноту, бо багато хто, досягнувши щастя, забули про неї. Але я, каже, не такий. Інший, тобто Никита, каже: ушанувавши друзів Твоїх, Владико, я сподіваюся, що у воскресіння стану з ними й з Тобою. Тоді ж і грішники загинуть, бо Він додає: уб'єш грішників."],"h":"Перелічу їх, і більше за пісок морський їх розмножиться"},{"v":"19","t":["Тут бракує слова «добре», щоб було так: добре, якби Ти, Боже, убив грішників; грішниками називає бісів і беззаконних людей. Убивство (смерть) бісів полягає в тому, щоб вони більше не діяли й не чинили зла; а смерть беззаконних людей — у тому, щоб вони почали відвертатися від пороку й навертатися до чесноти й більше не були грішниками. Або смертю останніх називає смерть тілесну: тим, хто перебуває без виправлення й невиліковний у злі, краще померти передчасно, щоб і іншим не заважали в прагненні до чесноти своєю зловмисністю й своїм прикладом.","Прим.: Вище значення цих слів, за поясненням Никити, може бути таке: злі й грішні думки віддаляють людину від Бога, як і написано: лукаві думки відлучають від Бога (Прем. 1:3). Але коли Бог, прихилившись до молитви, умертвить і погубить ці грішні й богопротивні думки, тоді людина може встати з земного пороху гріха й прибігти до Бога; і саме це означають слова: я встав, і я ще з Тобою, як був і раніше, — якщо, звісно, уб'єш грішників.","«Мужі кровей, відійдіть від мене»","Відійдіть, каже, від мене й тікайте від спілкування зі мною, убивці й кровожерні люди, що вбиваєте переможених і впійманих вами; бо всі такі людиновбивці належать дияволові, як ті, що вбивають одних ділом, інших словом і поганим прикладом свого життя. Утім, немала заслуга й у тому, коли хтось уникає спілкування з беззаконними людьми.","Прим.: За словами Євсевія, ці слова пов'язані з попередніми: бо хто сказав раніше, що друзі Божі для нього любі й дорогоцінні, той зрікається й проганяє від себе грішників. Слова Феодорита: тим, хто любить добрих людей, властиво відвертатися від тих, хто протилежної вдачі. Тому й каже, що коли Ти, Людинолюбче, убиваєш грішників, то тим більше я відвертатимуся від спілкування з ними, знаючи їхній дух: бо вони не слухають добрих порад, а через розбещеність серця відкидають їх."],"h":"Якби Ти вбив грішників, Боже!"},{"v":"20","t":["Відійдіть, каже, не спілкуйтеся зі мною ви, що з людей стали вбивцями: бо ви заздрісні, тобто честолюбні й любите порушувати спокій і зловмисними міркуваннями, і, як переклав інший, поганими порадами.","«Візьмуть марно міста Твої»","Згадані вище, веде далі, беззаконні люди марно житимуть у містах Твоїх, Господи; бо кожне місто й уся земля належать Господу, адже Господня земля і все, що наповнює її (Пс. 23:1). Чому ж такі житимуть у них марно? Бо вони залишаться безплідними для чесноти й не дістануть, за словами Феодорита, від закону жодної користі.","Прим.: Інший каже: марно піднеслися суперники Твої; тому й Золотоустий міркує: Давид тому старанно уникає злих, що вони піднеслися проти Божої слави, що суперечать і протиборствують Йому, і зневажають Його, і що вони марно жили в містах. А якийсь Карпатійський (можливо, Іоанн Карпатійський), чиї слова наведено в зводі Никити, каже: такі й єретики: вони для суперечки й марно беруть Божі міста, тобто тлумачать Писання. Але коли вони виганяють нас з одного міста, тобто вислову, ми прибігаємо до іншого, бо через порівняльний розгляд цих висловів відкривається шукане (поняття про спірний предмет). Бо не встигнемо сповнити Писання, як прийде Господь і явить нам перед Своїм світлом істину."],"h":"Бо ви заздрісні в думках"},{"v":"21-22","t":["Сказавши вище про друзів Божих: а для мене дуже шановні стали друзі Твої, Боже, — Давид тепер говорить тут протилежне про ворогів Божих: я, Господи, ненавидів тих, хто ненавидить Тебе; і як шана до друзів Божих у нього була надмірна, бо, каже, дуже шановні були, — так і ненависть до ворогів Божих так само була в ньому сильна, бо від гніву, яким кипів проти них, він знемагав, тобто згорав.","Прим.: Слова невідомого в Никити: той ненавидить мисленних ворогів досконалою ненавистю, хто ні порухом, ні дією, ні думкою не грішить, що означає найбільше й крайнє безпристрастя. А вороги Господа — нечисті духи й ідолослужителі, єретики й беззаконні люди. Слова блаженного Августина: досконала ненависть буває тоді, коли хтось ненавидить зло й любить природу, і хто, ненавидячи зло, не має ненависті до природи, тобто людської, що творить зло, і навпаки, люблячи природу, чи людину, не любить разом із нею і її зла, а любить тільки природу й ненавидить тільки зло. Згідно з цим сказав і Золотоустий: що ж? Невже не слід ненавидіти ворогів, хоч би вони й були еллінами? Слід ненавидіти, але не їх, а їхнє вчення, не людину, а злі діла й превратні думки їхні. Людина — творіння Боже, а оману — діло диявольське; тому не змішуй Божого з диявольським (Бесіда 33 на 1 Кор.). Феодорита: я прив'язаний до Твоєї любові, Владико; тому й люблю та шаную Твоїх істинних слуг, а тих, хто ненавидить Тебе, не тільки ненавиджу, а й гніваюся на них і знемагаю через них. Бо я ненавиджу їх як законопорушників, а жалію їх як людей і з природного співчуття до них змушений оплакувати їх, а через їхню велику розбещеність знову гидую ними."],"h":"Чи ж не зненавидів я тих, що ненавидять Тебе, Господи, і через ворогів Твоїх не знемагав я? Досконалою ненавистю зненавидів я їх, ворогами стали вони мені"},{"v":"23","t":["Як Давид говорить це після того, як на початку цього псалма сказав: Господи, Ти випробував мене й пізнав? На це відповідає бажання, щоб Бог випробував його ще різними спокусами для більшого переконання тих, хто не знав чесноти його терпіння, щоб, пізнавши це, вони за силою наслідували його.","«Досліди мене й пізнай стежки мої»"],"h":"Випробуй мене, Боже, і пізнай серце моє"},{"v":"24","t":["Сказане вище Давид повторює й тут. Або промовляє ці слова до Бога, бажаючи, щоб Він випробував його знову заради тих, хто кривдив його, тобто щоб багатьма випробуваннями від Бога переконав їх у тому, що він зовсім не кривдив їх. Або хоче зазнати випробування для того, щоб у разі неповної його чистоти від гріха це відкрилося через випробування, і так він міг виправити себе в тій омані, що він, не бувши чистим, думає, ніби чистий.","Прим.: Слова Феодорита: молю, каже, Тебе, єдиного Лікаря душ: дослідь моє життя старанно й випробуй рухи й поривання мого розуму; і якщо щось знайдеться в них противне Твоїм законам, прошу вилікувати це Твоєю мудрістю й настановою в ході вічному. Це доповнює Золотоустий так: що це за дорога вічна? Та, що веде до неба й якій немає кінця. Як усе інше тимчасове й закінчується теперішнім життям, а блага, що залежать від цієї дороги, не одноденні й не тимчасові, — така й чеснота: вона приносить безперервні плоди. Як же можна бути наставленим на цю дорогу, що не має кінця? Діставши від Бога допомогу й додаючи можливе й від себе."],"h":"І подивися, чи не на дорозі беззаконня я, і настав мене на дорогу вічну"}],"139":[{"v":"1","t":["Прим.: Феодорит вважає, що Давид склав цей псалом під час гоніння на нього від Саула; тому й просить Бога звільнити його від нього. Але й людська природа цим псалмом просить Бога захистити її від мисленних ворогів — бісів — і обернути неправду тих, хто чинив їй зло, на їхню голову."],"h":"На кінець, псалом Давидів"},{"v":"2","t":["Звільни мене, Господи, так починає, від людини лукавої, або лиходія; тут злим названо неспокійного, бо зло завдає неспокою й утоми тому, хто його чинить або присвоїв собі; тому й Соломон сказав: якщо ти злий, сам зачерпнеш собі зла (Притч. 9:12). Потім відкриває, кого він називає злим, а саме — неправедну й беззаконну людину. Оскільки від такої (злої й неправедної людини) ніхто не може легко сховатися сам собою, то Давид просить допомоги в Бога, щоб із цією божественною допомогою, як каже Золотоустий, звільнитися від неї. Подивись при цьому й у 42-му псалмі пояснення слів: від людини неправедної й підступної збав мене. Отже, оскільки в попередньому псалмі Давид сказав: мужі кровей, відійдіть від мене, а так само й у 6-му псалмі: відступіть від мене всі, хто чинить беззаконня, — інакше кажучи, Давид цими словами показав, що він сам собою відвертається й уникає злих і неправедних людей, — то тепер просить Бога допомогти йому цілковито відвернутися від таких людей; бо треба, щоб людина не була бездіяльною, а спершу сама робила те добро, що залежить від неї, а потім просила Бога допомогти їй, хоча й це добро зі свого боку вона чинить із Божою допомогою, як сказано: без Мене не можете робити нічого (Ін. 15:5). Бо й Бог не допомагає тобі, людино, коли ти недбаєш і не стараєшся робити добро, і навпаки, ти не можеш учинити нічого доброго своїм старанням, якщо Бог не допоможе тобі.","Прим.: Слова Золотоустого: де тепер ті, хто питає: навіщо ці звірі? навіщо змії? Бо ось і людина, хоч і жива істота, але виявляє в собі ще більшу лютість, не за природою, а за налаштуванням. Тому пророк більше просить Бога позбавити його від неї й кличе Його на допомогу проти цього; бо той звір є тим, чим він є, а людина навмисно чинить зло й, прикриваючись багатьма личинами, тим страшніша, і часто, носячи на собі овечу шкуру, усередині ховає вовка. У таких часто ховається й так пускає стріли й диявол. Бо всюди багато злих задумів з боку злої людини, лютого диявола й нестерпної спокуси. Тому ми й у молитві кажемо: не введи нас у спокусу, але визволи нас від лукавого. Тут лукавим називає людину, а коли йдеться про диявола, то просто називає його лукавим, бо він став батьком зла й переважно зветься злим. А неправедним називає не просто неправедного щодо грошей, а й узагалі щодо всього."],"h":"Визволи мене, Господи, від людини лукавої, від мужа неправедного збав мене"},{"v":"3","t":["Ці, веде далі, лукаві й неправедні люди задумали неправедні, беззаконні й шкідливі діла в своєму серці й увесь день, тобто все своє життя, готувалися чинити війни й заколоти, діючи то проти братів, то проти інших: бо надмірна їхня зіпсованість не дає їм заспокоїтися, а спонукає їх часом таємно, хитро й підступно повставати на своїх братів, а часом і явно протиборствувати їм. А війною називається й хитрість, або злий задум, і всяке інше збурення та взаємне заподіяння шкоди одне одному ділом, чи словом, чи думкою, за словами Золотоустого.","Прим.: Слова того ж Золотого Святителя: а що найбільше становить їхню злоякісність, це те, що вони не тільки хитрі, а злі й готові до повстань і воєн, і все життя ведуть війну, і то тоді, коли, якби лише хотіли вести війну, могли б мати інший предмет: бо слід було протистояти гріхам і ополчатися проти диявола. А вони пускають стріли в своїх ближніх, і, що страшніше, не захоплені до того ненароком, а з попереднім міркуванням про це; бо «задумали» означає: зі старанням, з усією охотою (задумали). Феодорита: бо не тільки віддавалися злим думкам, а й додали діла до думок."],"h":"Які задумали неправду в серці, увесь день готували війни"},{"v":"4","t":["Ці, каже, злі й неправедні люди нагострили свій язик, щоб випустити згубну отруту своїх хитрих і шкідливих слів, і під губами в них, тобто в їхніх устах, перебуває зловмисне й душешкідливе слово, що подібне до отрути аспида, бо пошкоджує й губить невинних. Бачиш, улюблений, як злоякісність перетворила таких людей на звірів, аспидів і зміїв, не змінивши їхньої природи, а обернувши їхню вдачу, за словами Золотоустого, на нелюдяність і жорстокість.","Прим.: У Золотоустого написано: отрута ж аспидів під губами їхніми завжди. Бо пауза, що тут стоїть (διάψαλμα), означає «завжди». І про цю паузу можеш прочитати в першому томі, у 7-му розділі передмови.","Прим.: Слова Євсевія: вони готові до обману, подібно до того змія, що колись ошукав у раю жінку; бо й він приступав до жінки з удаваною дружбою, показуючи себе таким, що дбає й старається про неї, а в своїх словах приховував смертоносну отруту переступу. Такі, на мою думку, і безбожні єретики, і ті, хто мудрістю цього світу озброюється на війну й гострить свій язик, ховаючи водночас під губами отруту аспидів, тобто якихось злих сил. Феодорита: бо Саул хитрощами часто намагався знищити його і, багато разів поклявшись і вживши дружніх слів, переступав свої клятви. Цю таємну ворожнечу й приховану хитрість пристойно уподібнив отруті плазунів."],"h":"Нагострили язик свій, як у змія, отрута аспидів під губами їхніми"},{"v":"5","t":["Знову й тут Давид повторює сказане вище, щоб поширити й посилити своє прохання. Грішний же й неправедний у цьому місці — кожна людина, що грішить у будь-який спосіб; також той, хто кривдить себе чи іншого; бо такий неправедник кривдить самого себе постійно й завжди кожним гріхом, який чинить, а іншого не кривдить постійно й завжди кожним гріхом, який чинить (так, наприклад, той, хто вбиває себе, не кривдить іншого). А Писання часто як узагалі всяку чесноту називає правдою, так, навпаки, усі злі діла називає неправдою.","Прим.: Феодорита: молитва, що пасує праведникові! Бо він просить не загибелі ворогові, а спасіння собі.","«Які задумали підставити ногу стопам моїм»"],"h":"Збережи мене, Господи, від руки грішника, від людей неправедних визволи мене"},{"v":"6","t":["Згадані вище, веде далі, злі й неправедні люди намагалися перешкодити богоугодному й законному ходові мого життя й діяльності в суспільстві (член τοῦ тут ужито зайво, за звичаєм єврейської мови); ці слова взято з прикладу тих, хто підставляє свою ногу під ноги тих, що біжать перед ним, щоб звалити їх на землю й перешкодити їхньому бігу. А горді — це всі беззаконні, бо вони через гордість нехтують Божим законом, як сказано й в іншому місці, що горді переступали закон до краю (Пс. 118:51). Отже, вони, каже, сховали для моїх ніг сітки й тенета, тобто таємні задуми, щоб упіймати мене. До того ж поклали при стежці перешкоди, тобто біля й посеред самої дороги, якою я ходив, щоб я, ідучи нею необережно, ненароком упав через них. Давид різними образами сіток, мотузок і перешкод поширює слово про задуми своїх ворогів і каже, що все це вони сховали й поклали на дорозі, щоб зобразити старанність і винахідливість їхніх багатоплетених злих хитрощів.","Прим.: Золотоустого: ніщо не може бути несправедливішим за тих, хто плекає в собі злобу, бо вони передусім шкодять своїм душам. Бо коли вони стають причиною спокуси; коли стають винуватцями зневаги Божої слави в безумних; коли, отримавши душу й тіло від людинолюбного Бога, не дбають про віддяку, а, насолоджуючись такою красою світу й таким благом, віддають Благодійникові протилежними діями, — то що може бути несправедливішим за них? що невдячнішим? І, що ще важливіше й сильніше показує надмір їхньої злої вдачі, вони намагаються чинити зло іншим. Задумали, каже, підставити ногу стопам моїм. А якщо їхній задум не здійснився, то це справа Божого людинолюбства: Він розітнув їхні злі задуми. Хочеш знати, як і диявол кладе такі самі петлі (мотузки)? Подивись, що сталося з Йовом. Що могло бути ширшим за них? Що довшим? Що ближчим, коли він улаштував сітку не тільки через родичів, і друзів, і дружину, а й через саме його тіло? Феодорита: гордим називає самого Саула, а сіткою, мотузками й перешкодами — різні задуми, слова й приховані дії. А це сказано не власними словами, а взятими з подоби мисливців, що розставляють сильця, петлі для ніг і сітки."],"h":"Сховали горді сітку для мене, і мотузками розтягнули сітку для ніг моїх, при стежці спокуси поклали мені"},{"v":"7","t":["Ці, додає, вороги мої задумали проти мене це; але я, перебуваючи серед таких небезпек, кликав тільки Тебе, Боже, і казав: Ти мій Бог, не зневаж Свого творіння, а почуй моє благання й визволи мене від усього того.","Прим.: Золотоустого: це ознака вдячної душі, властивість любомудрого — не вдаватися до людської допомоги, ні до смертних засобів, а дивитися на небо й кликати Всюдисущого; не сумувати й не бентежитися. Євсевій: в одних бог — черево, а в інших — багатство й те, що живить пристрасть сріблолюбства. Бо чим хто переможений, тому й поневолений. А я маю за Бога Тебе, єдиного істинного Бога, і я Твій; тому до Тебе й прибігаю й Тобі молюся. Феодорита: а я, знехтувавши все людське, присвятив себе Тобі, і знаю Тебе як Господа й Бога, і від Тебе чекаю допомоги."],"h":"Сказав я Господові: Ти Бог мій; почуй, Господи, голос благання мого"},{"v":"8","t":["Господи, Господи, каже, Ти сила, що спасає мене; Ти покривав мене, коли я був у боротьбі, тобто беріг мене й поставив у безпеці не тільки від того, щоб мене поранили мечем чи стрілою, а навіть від самого сонячного проміння, що докучало мені своїм палінням (бо це, за Золотоустим, виразив дієсловом «отінив»). Давид тут з подякою визнає раніше явлені йому Богом благодіяння, щоб цією вдячністю ще більше притягнути до себе Божий захист і допомогу.","Прим.: Слова Золотоустого: дивись, яка любов у того, хто говорить, — і самим повторенням (Господи, Господи), і додаванням «спасіння мого» показує велику прихильність; а ім'ям отінення вказує на швидкість допомоги, ніби кажучи: досить Тобі тільки з'явитися, і все скінчиться. Інший каже, що слова «Ти отінив» ужито замість: я мав Твою руку, що боролася за мене й покривала мою голову, щоб вона не була поранена стрілами, пущеними в мене. Феодорита: і це я пізнав із досвіду: бо коли я вступив у єдиноборство з Голіафом і коли ополчався проти чужоплемінників, Ти обгородив мене довкола Своєю допомогою, як щитом."],"h":"Господи, Господи, сило спасіння мого! Ти отінив голову мою в день битви"},{"v":"9","t":["Не допусти, каже, Господи, щоб мене віддано грішникові-бісу за моє зле бажання: бо й мені, як людині, трапляється часом мати зле бажання. Але через це прошу Тебе не засудити мене й не кинути в руки демона. Грішник — також і беззаконна людина.","Прим.: У перекладі Симмаха: не дай, Господи, бажань беззаконного, тобто, за поясненням Золотоустого, не допусти йому здійснити те, чого він бажає проти мене. Інший же, тобто Никита, вираз «через бажання моє» пояснює так: я бажаю, каже, спасіння. Отже, не залиш мене, щоб я, ухилившись від нього, не віддався сатані. Або й так: моє, каже, бажання — не відпасти, а в грішників — протилежне. Тому молю Тебе: не відбери від мого бажання й не віддай їм; а це може статися тоді, коли Ти залишиш мене. До цього можемо додати із Золотоустого таке: не сказав «чого він бажає», а «через бажання моє», тобто не дай і дрібки з того, чого він бажає. Бо такі злі: вони з великим бажанням складають задуми проти ближнього. Безіменного: і Писання називає їх нещасними: горе, каже, тим, хто веселиться злом і радіє злому розбещенню (Притч. 2:14). Бо є такі розбещені, що чужі біди вважають своєю розрадою в нещастях.","«Задумали проти мене; не залиш мене, щоб вони не піднеслися»","Вороги, каже, мої чуттєві й мисленні склали проти мене задуми й хитрощі; тому прошу Тебе, Господи, не допусти, щоб вони перемогли мене, щоб через таке залишення мене вони не загордилися й не озлобилися ще більше, хвалячись своєю перемогою наді мною."],"h":"Не віддай мене, Господи, через бажання моє грішникові"},{"v":"10","t":["Оточенням Давид називає тут сітку й підступ (або суд і превратні поради). Голова, каже, підступу моїх ворогів проти мене, на яку вони особливо сподіваються, — ця, кажу, голова, за словами Золотоустого, покриє й знищить їх самих. Її ж він назвав і трудом їхніх уст, бо вони багато трудилися, роздумуючи й часто розмовляючи про неї, і бо з великим трудом винайшли її. Тим, каже, злом, яким сподівалися погубити мене, вони самі себе погубили. Або трудом уст назвав злий задум і хитру пораду, бо вона згубна, за словами Золотоустого, і погибельна для самого свого винуватця.","Прим.: Слова того ж Золотого Святителя: брати Йосифа, що хотіли зробити його рабом і погубити, самі зазнали, як заслуговували, рабства й смерті. Авессалом, що через своє безмежне честолюбство хотів погубити батька, сам був упійманий ним. За іншим тлумачем, тобто Никитою, ці слова пояснюються більше в моральному значенні так: Бог повелів завжди стерегти голову змія; а голова й ніби початок гріхів — це помисел і гріховний прилог. Отож спочатку плотолюбний і хтивий помисел, навіяний душі ворогом, вирощує й збирає довкола себе багато інших мерзенних помислів. Тож першу думку й підступ злих помислів ми тут вважаємо головою. Тому коли перша поява злого помислу буде нами відкинута й не прийнята в серце, то вона покриє й знищить усі інші помисли, що виникають слідом за тим прилогом; і труд, який узяли на себе біси, щоб сіяти в нашому серці ці підступи, обернеться проти них, не завдавши нам жодної шкоди. Феодорита: від своїх же, каже, злих хитрощів нехай упадуть, і що влаштовували проти мене, нехай самі понесуть, і гіркота, що готується для мене, нехай цілком покриє тих, хто її творить. І сам диявол, що має довкола себе злі полчища бісів, теж є головою їхньої злоби."],"h":"Голова оточення їхнього, труд уст їхніх покриє їх"},{"v":"11","t":["На грішників, веде далі, моїх ворогів упадуть не просто вуглини, а разом із вогнем, тобто впадуть на них дуже розпечені вуглини й з великим жаром. А під цими вуглинами ти маєш розуміти покарання від Бога, що, подібно до палаючих вуглин, палить і мучить грішників. Це Давидове пророцтво про його ворогів, бо вогонь, посланий від Бога з неба, багато разів падав на багатьох грішників і спалював їх, а особливо на содомлян.","«Повалиш їх у стражданнях, і не встоять»","Ти, додає, Господи, повалиш грішників покараннями й лихими стражданнями, що так виснажать їх, що вони зовсім не зможуть витримати цього виснаження, а при першій поразці чи ударі впадуть у погибель від надмірної дії покарань.","Прим.: Інший перекладає: повалиш їх у безодні, і не встоять. Феодорита: а це сталося з Саулом у битві з чужоплемінниками, бо він закінчив життя, заколовши себе."],"h":"Упадуть на них вуглини вогненні"},{"v":"12","t":["Людина, каже, злоязика, тобто нестримана на язик, балакуча й нерозважлива, або та, що любить чвари й сварки, не матиме успіху в своїх ділах на землі, а впаде й загине і душею, і тілом.","Прим.: Золотоустого: Давид цим показує, що зло само собою може погубити тих, хто плекає його в собі. Бо трапляється, що злоязикого ще на землі спіткає його зло. Такий і наклепник: він усім ворог, нестерпний, тяжкий, нестерпимий, як, навпаки, великодушний, лагідний і той, хто вміє мовчати, — твердий, постійний і всім приємний.","«Мужа неправедного злі вловлять на погибель»","І інший премудрий сказав: беззаконня ловлять мужа (Притч. 5:22). А оскільки часто ловлять, на подобу здобичі, і на спасіння й користь душі, як упіймана словами Господа самарянка і як апостоли вловили народи, то Давид додав тут «на погибель»: неправедного мужа зло потягне на його погибель, за словами Золотоустого. І те, й інше, тобто і вищесказаний, і теперішній вислови Давидові, повчальні й назидательні.","Прим.: Той самий Золотоустий каже: дивись знову, як злоба здатна сама погубити тих, хто її плекає: бо він гине через свою злу вдачу, як через свою недугу; адже зла вдача може й сама, без жодного стороннього покарання, погубити душу, сповнену нею. Але чому вжив вираз про ловлю? Щоб ти бачив її неминучість; щоб ти, попри те, що, чинячи неправду, досі ще не попадаєшся, не покладався на це. Бо така ловля не завжди буває вдала й не відразу; але хоч і не ловлять диких звірів, яких переслідують, усе ж вони не в безпеці. Так і душа нехай не покладається на те, що, чинячи неправедно, вона ще не впіймана; бо колись буде впіймана. Якщо хочеш бути поза небезпекою, то перестань це робити, і будеш у великій безпеці. Чому ж покарання за зло не спіткає відразу слідом за ним? Через людинолюбство Владики: якби Він хотів відразу карати кожного грішника, то передчасно більшу частину людей було б забрано."],"h":"Муж язикатий не матиме успіху на землі"},{"v":"13","t":["Хоча Божа помста часто зволікає спіткати кривдників за пригноблених і утискуваних, яких тут називає убогими й бідними, проте добре каже: я знаю, що Господь неодмінно вчинить суд і помсту за них — чи в теперішньому житті, чи в майбутньому. А мету цих слів Давид має таку: з одного боку подати розраду скривдженим, а з другого — налякати й напоумити тих, хто кривдить їх, як пояснює Золотоустий.","Прим.: Він додає: щоб ні перші (скривджені) не знесилювалися в скорботі, ні другі через відстрочку не стали ще недбалішими. Бо відстрочка веде до покаяння, а впертого часто віддає тим сильнішому покаранню, і цілком справедливо: бо, маючи стільки доказів благості, він не став кращим. Бо подумай, яке велике Боже людинолюбство, коли відданим Йому Він дозволяє тільки страждати й не заступається за них, бажаючи виправити кривдника покаянням. Орігена: це пророцтво про майбутній суд, за яким нечестиві будуть віддані вогню, а праведні ввійдуть у спокій. Тому й Соломон, указуючи на це, сказав: бо всяке діло Бог приведе на суд (Екл. 12:14). Приємне ж закінчення дано псалмові, бо наприкінці написано те, що праведникам зберігається надія."],"h":"Я пізнав, що Господь учинить суд убогим і помсту за бідних"},{"v":"14","t":["Хоча, каже, Божий суд на користь праведників і зволікає, але праведники не спокушатимуться цим зволіканням, а дякуватимуть Тобі, Боже, знаючи, що все це Ти чиниш з розрахунком, премудро й на користь.","«І оселяться праві з лицем Твоїм»","Правими Давид називає тут згаданих вище праведників. Праведники, каже, житимуть разом із Тобою, Господи, тобто разом зі спогадом про Тебе, завжди перебуваючи з ним і ніколи не віддаляючись від нього. Або правими називає апостолів, а лицем Божим — Христа, як образ Його єства. Так і Сам Христос сказав: Отче, хочу, щоб там, де Я, і вони були зі Мною, щоб бачили славу Мою (Ін. 17:24). Бо найвище благо полягає в баченні Бога. Утім, ці слова можна розуміти й інакше: праведники загалом — це ті, хто вправляється в чесноті, а праві — ті, хто чинить чесноту з розсудом і розрізненням. А оскільки цей псалом згадує і про майбутній суд, і про Христа та апостолів, то це спонукало декого дати цьому псалмові такий напис: на кінець, псалом Давидів.","Прим.: Замість «з лицем Твоїм» Симмах переклав «перед лицем Твоїм», позначаючи цим те, що вони (праведники) очищеним розумом побачать Бога лицем до лиця (Оріген).","Прим.: Золотоустого: перебуваючи завжди з Тобою, вони ніколи не стануть відступниками; хоч би що з ними сталося, вони ніколи не обурюватимуться й не ганитимуть пригод; бо це властиво незмінній і непохитній душі — не вимагати від Владики звіту. Тому й Павло казав: а ти хто, людино, що сперечаєшся з Богом? Чи скаже виріб тому, хто його зробив: навіщо ти мене так зробив? (Рим. 9:20)."],"h":"Однак праведні прославлять ім'я Твоє"}],"140":[{"v":"0","t":["Псалом Давидів","Прим.: Слова Феодорита: і цей псалом Давид склав під час гоніння на нього від Саула; у ньому він просить Божої допомоги; інші кажуть, що цей псалом промовлено від особи вавилонських полонених. Слова Золотоустого: слова цього псалма знають, сказати б, усі й співають у кожному віці, але думки не розуміють; вони носять при собі запечатаний гаманець, що немало осудливо для нас — щодня співати й ніколи не постаратися пізнати думку того, що співають, а сидіти при скарбі, вкритому тінню. Я думаю, що Отці не марно встановили читати цей псалом щовечора, і не через одне лише слово, що в ньому міститься: підняття рук моїх — жертва вечірня; а уставом покладено читати цей псалом як якісь спасенні й очисні від гріхів ліки, щоб усі гріхи, що чинимо протягом дня, хоч би де ми були, досягнувши вечора, ми скинули з себе через цей духовний спів."]},{"v":"1","t":["Я, починає, кликав до Тебе, Господи, голосом і зойком серця, розпаленого й пройнятого скорботою; тому вислухай мене. Бо таким мисленним голосом серця кличучи, Мойсей був вислуханий Богом, хоча устами й мовчав. Такий голос піднесла від серця й цнотлива Анна, дружина Елкани, хоча й не чути було її уст; тому й при своїй неплідності народила Самуїла. Таким самим, каже, мисленним голосом серця я кликав до Тебе, Господи, голосом, чутним для Твоїх вух, а не одним лише чуттєвим голосом уст, яким молилися й примножували своє благання юдеї та не були вислухані; бо хто кличе устами чуттєво, той напружує все своє тіло назовні, виснажуючи всю свою силу; а хто кличе серцем мисленно, той зосереджує весь розум і всю душу всередині й збирає всю свою силу; тому й гідний бути вислуханим Богом.","Прим.: Золотоустий: тож що Він каже: я кликав? Кликанням тут називає не тілесне, а внутрішнє, що йде з розпаленого серця: бо такого зойку вимагає Бог — від того, хто зосереджує думки, не дозволяє розсіяності, і не тільки такого, а й благання до Нього. Бо багато хто стоїть на молитві, але не кличе до Бога; уста їхні кличуть до Бога й часто вимовляють Боже ім'я, а розум не розуміє жодного слова корисної молитви. Також: не всі слова молитви корисні, а тільки ті, що підносяться з великої прихильності. Бо й фарисей, здавалося, молився багато, але самому собі, бо перебував у гріху гордості.","«Почуй голос благання мого, коли кличу до Тебе»","Почуй, каже, Господи, голос мого благання, бо я кличу до Тебе мисленно й усім своїм серцем, як сказано вище; адже Бог не зважає на чуттєвий голос молитви того, хто не кличе так, тобто мисленно й від усього серця.","Прим.: Слова Золотоустого: зауваж і іншу досконалість молитви, за яку просить вислухання, тобто щоб удостоїлася Божої уваги й неусипних очей. Яка ж це? Коли хтось молиться не проти ворогів і не про багатство, чи силу, чи славу, чи щось тлінне з цього світу, а про ті безсмертні й нетлінні блага. Бо не тільки не слід молитися на зло ворогам, а й гнів на них треба викорінити. Тому й Павло каже: хочу, щоб чоловіки молилися, підносячи чисті руки без гніву й сумніву; тобто хоч маєш ворога, погаси в собі гнів і тоді приступай до Владики; і не тільки устами не кажи нічого проти нього, а й розум очисти від отрути. І якщо така буде молитва й ти ревно кличеш до Бога, то ще до закінчення молитви будеш вислуханий: ще, каже, ти говоритимеш, а Він уже скаже тобі: ось Я тут."],"h":"Господи, я кликав до Тебе, вислухай мене"},{"v":"2","t":["Два жертовники були в давньому Божому храмі, за поясненням Золотоустого: один золотий, а другий мідний; золотий був призначений для куріння фіміаму (кадила), а мідний — для інших жертв. Кадило готували з дорогоцінної й чистої речовини за установою закону, тому й було приємне перед Богом, коли куріло, і з цієї причини, і тому, що прообразувало нове богослужіння — благодатне, євангельське. Тож Давид просить так: нехай направиться й буде приємна Тобі, Господи, моя молитва, як те чисте, найпахучіше куріння кадила, що в законі приносилося Тобі, коли моє серце розпалюється вогнем сильного бажання любові, як розпалюється вогнище золотого жертовника й видає пахощі фіміаму. І про кадило досить. А щодо жертви вечірньої зауважимо, що священникам було поставлено за обов'язок безперервно щодня приносити в жертву двох ягнят, тобто баранців, одного вранці, а другого ввечері, хоч би ніхто з євреїв не приносив іншої жертви; тому й ці жертви з двох овечих плодів називалися жертвами безупинними, бо їх безупинно, тобто безперервно, приносили. Ось що, каже Писання, ти приноситимеш на жертовник: ягнят однолітніх без вади двох щодня на жертовник, безперервно, у жертву безупинну; одне ягня приноситимеш уранці, а друге ягня ввечері, у жертву безперервну в роди ваші (Вих. 29:38-39). І ці жертви з двох ягнят були завжди чисті й приємні Богові, бо не приносилися за гріхи; тоді як інші жертви, що їх приносив народ, не завжди були приємні й чисті, бо багато разів оскверняла їх нечиста вдача тих, хто приносив. Тому ці дві жертви були цінніші за інші, а з цих двох жертва, що приносилася ввечері, була важливіша за ранкову; бо ранкова жертва закінчувалася вечірньою, і вечірня була завершенням щоденного священнодійства і, за зауваженням Золотоустого, замикала служіння в храмі. Отже, Давид каже: нехай направиться й буде чистим і приємним Тобі, Господи, підняття моїх рук під час молитви, як приємна Тобі жертва вечірня; а приємною молитва буває тоді, коли як уста, що моляться, чисті від мерзенних слів, тобто лайки, лихослів'я, осуду й обмов, так і серце, що молиться, чисте від мерзенних, богохульних і злих помислів, і коли руки, які підносимо під час молитви до Бога, чисті від користолюбства, грабунку й усякої іншої беззаконної дії.","Прим.: Слова Євсевія: молитва, що направляється й приємна, — це молитва тих, хто просить істинних благ; бо хто не так молиться, того молитва відкидається, як погасле кадило, і розвіюється, як смердюче куріння. Божественного Василія: без сумніву, Бог в Ісаї відкидає старозавітне куріння, коли каже: кадило — гидота Мені. Бо воістину мерзенна та думка, ніби Бог, люблячи насолоду нюху, установив складний фіміам; огидне нерозуміння того, що пахуче куріння Господу — це освячення, що звершується в тілі душевною цнотливістю. Золотоустого: тож нехай кадилом твоїм буде тіло; і дивись, щоб ти не наповнив це кадило гноєм; а такі ті, хто вимовляє мерзенні й нечисті слова. Бо як кадильниця, крім вогню й фіміаму, не повинна містити в собі нічого нечистого, так і язик, крім святині й хвали, не повинен виносити жодного скверного слова. Так само й руки мають бути кадильницею: бо ти приносиш кадило не на мідному й не на золотому жертовнику, а в храмі духовному, що цінніший за той. То була бездушна речовина, а в тобі живе Бог, і ти член Христів і тіло чесне (дороге). Інший каже: Давид до мисленної молитви додав і слова «підняття рук моїх»; бо, говорячи про мисленне, він мав згадати й про діяльне, про дії тілесні. Євсевій: сказав про вечірню молитву, а не про ранкову, тому що добрі діла, звершувані до останнього подиху й до самого кінця життя (що й означає вечір), Бог визнає кращими за всяку жертву. Феодорита: згадав про вечірню, а не про ранкову, без сумніву, тому, що перебував у бідах і скорботах, а біда подібна до темряви й ночі. Тут зауваж, що мисленні вправи уподібнив фіміамові, як найтонші й найчистіші, а заняття, що полягають у діях, як грубіші, назвав жертвою."],"h":"Нехай направиться молитва моя, як кадило перед Тобою, підняття рук моїх — жертва вечірня"},{"v":"3","t":["Знаючи, що уста бувають причиною багатьох зол, коли немає дбання про них і їм дозволяють говорити необдумано все, що спаде на думку, як, навпаки, ті самі уста бувають причиною й багатьох благ, коли на них зважають і людина їх стереже, і що для цього потрібні старання, подвиг і особливо Божа допомога, — Давид тому просить Бога про допомогу в стереженні уст. Так і божественний Золотоустий каже, що спритність язика буває причиною незліченних бід, як, навпаки, стереження його — незліченних благ. Бо як якомусь домові чи місту не на користь ворота й міцні стіни, коли при них немає сторожів, що знають, коли треба замкнути ці ворота й коли відчинити, так немає користі від уст і язика людини, коли їх не стережуть, за словами Золотоустого.","А сторожею для уст служить увага розуму, тобто коли розум знає, які слова треба говорити, а які тримати в серці; бо, за словами Сираха, багато хто впав від вістря меча, але не стільки, скільки впало від язика. Блаженний, хто сховався від нього (Сир. 28:21-22). Отже, постав, каже, Господи, сторожу моєму ротові й двері огорожі, тобто варту довкола моїх уст; бо одне й друге — і сторожа, і огорожа — цілком одне й те саме.","Прим.: Слова Золотоустого: що таке сторожа уст? Страшний звіт, приставлений до них, що має напоготові (у руках) вогонь, готовий обпекти тих, хто вживає уста нерозважливо. Його постав воротарем і сторожем, щоб грозив сумлінню; і ти ніколи невчасно не відчиниш цих дверей; разом із ним приставь і іншого, що нагадує слова: за кожне пусте слово даси відповідь у день суду.","Прим.: Слова Золотоустого: бачиш, яке знання? Бачиш мудрість? З чого починає молитву? З найбільшого з подвигів. Тож стережімо уста, приставляючи до них розсудливість, щоб безупинно замикала їх, — не для того, щоб вони завжди були замкнені, а щоб відчинялися в належний час. Бо трапляється, що часом мовчання приносить більше користі, ніж мова, а часом і мова більше, ніж мовчання. Тому й премудрий каже: є час мовчати й є час говорити (Екл. 3:7); і Сирах сказав: якщо маєш думку, відповідай, а якщо ні, то нехай рука твоя буде на устах твоїх (Сир. 5:14); і в іншому місці: словам твоїм зроби вагу й міру, і для уст своїх зроби двері й засув (Сир. 28:29); і в іншому місці: не стримуй слова в час спасіння (Сир. 4:27). Григорія Ніського: Творець поклав язикові дві огорожі — зуби й губи, щоб затримувати нерозважливі слова. Тому й та найтонша шкірка (тканина), що через нижню губу вгамовує язик, називається (у грецькому) вуздечкою, щоб не вимовляв безчинних і некорисних слів. Кирила: знав блаженний пророк, що бездоганне вживання слова — діло похвальне; бо хто не грішить у слові, той досконалий і може вгамувати все тіло (Як. 3:2). А вільне й свавільне вживання язика, нестримно схильного до всякої неправди, — як може хтось не осуджувати? Філона Юдея: здається, природа влаштувала людям губи для двох найпотрібніших речей: по-перше, для мовчання, бо вони — найміцніший захист і перепона для голосу; а по-друге, для вираження думки, бо через них слова течуть рікою; і коли вони стулюються, слово стримується, а коли розтуляються, воно виходить. Але слід говорити значно менше, ніж чуємо; адже й природа, співмірюючи потребу слова зі слухом, за словами Василія Великого, улаштувала в нас два вуха й один язик: тому, навчаючись, треба слухати вдвічі, а відповідати скромно й небагато більше, ніж питають. Феодорита: Творець дав язикові дві огорожі — зуби й губи, щоб цим стримувати його нерозважливі пориви. Утім, пророк просить і іншої охорони, остерігаючись, щоб не вимовив у своїй скарзі чогось непристойного. Бо що він і під час гонінь від Саула ніколи не любив вимовляти жодного лихослів'я, про це свідчить історія."],"h":"Постав, Господи, сторожу устам моїм і двері огорожі довкола губ моїх"},{"v":"4","t":["Не допусти, веде далі, Господи, щоб моє серце схилялося й падало до вимовляння устами лукавих слів і до непристойних спогадів і думок через роздуми; це, за словами Золотоустого, легко здійсниться тоді, коли й при зовнішніх устах поставлено сторожу. До того ж не допусти моєму серцю схилитися не тільки до тих лукавих слів, а й до вигадування виправдань своїм гріхам; бо першостворені, учинивши гріх, виправдовувалися: Адам указував на Єву, що вона ошукала його, а Єва своєю чергою — на змія, що він посміявся з неї. Так само й убивця виправдовує вчинене вбивство поривом свого гніву, і перелюбник виправдовується пристрастю своєї хоті, грабіжник виставляє свої потреби й бідність, а інший грішник указує на іншу причину, хоча не це спонукальні причини гріха, а їхні недбалість і неуважність. І це бачимо з прикладу дбайливих і уважних, які не чинять подібних гріхів. Бо диявол, знаючи, як каже Золотоустий, що сповідь і відкриття гріха вмилостивлюють Бога, а запирання й приховування гріха спонукають Бога до гніву, — цей нечистий дух схиляє грішників до самовиправдання й до того, щоб казали, ніби не вони згрішили, а щось інше поза ними було причиною гріхів.","Прим.: Золотоустого: не те, каже, що Бог схиляє серце, — зовсім ні, а це означає те саме, що «не допусти схилитися, не допусти звернутися до злих думок»; бо тут, у серці, джерело зла й добра. А слова лукавства — ті, що роблять інших злими: що в тілах чинять заразні подуви повітря, те вони в душі. Це найбільше веде до погибелі, коли душа, що грішить, віддаляється від страху й вигадує якісь виправдання, винаходячи слова, що виправдовують пристрасті: зло — гріх, але ще гіршим він стає через запирання після гріха. Тож коли ти згрішив, скажи, що згрішив, і немає нічого вищого за таке виправдання; цим ти вмилостивлюєш Бога й себе робиш непохитнішим щодо падіння в ті самі гріхи. Пристойно пояснює це й Феодорит: блаженний Давид міг подумати в собі так: Саул — ворог і супротивник, що бажає мені смерті; тому не буде несправедливості, якщо вбити його, бо й закон каже: полюбиш ближнього свого й зненавидиш ворога свого. Але, передбачаючи євангельське життя, він хотів жити ним; тому й просить про те, щоб не вигадувати жодного виправдання гріхові.","«З людьми, що чинять беззаконня»","Ці слова залежать від попередніх: не допусти, каже, Господи, моєму серцю вигадувати виправдання разом із беззаконними чи грішними людьми; бо вони, учинивши гріх, виправдовують себе в ньому різними причинами.","«І не буду в лічбі з вибраними їхніми»","Коли, каже, Ти, Господи, допоможеш мені й я не уподібнюся беззаконним у виправданні гріхів, то я ніяк не спілкуватимуся й не єднатимуся не тільки з нікчемними з беззаконних, а й зі значнішими з них.","Прим.: Інший тлумач каже: і нехай не скуштую їхніх солодощів; інший: не буду в їхніх дворах на їхніх розвагах; пояснюючи це, Золотоустий каже: тут говорить апостольське слово, що треба уникати й насолод, і бенкетів із тими, у кого оселилися гріховні дії. Феодорит: це нехай роблять ті, хто чинить беззаконня, а в мене нехай не буде жодного спілкування з ними, хоч би вони були вкрай щасливі; бо тут вибраними зі злих називає тих, хто живе в благополуччі."],"h":"Не схили серця мого до слів лукавства, щоб вигадувати виправдання гріхам"},{"v":"5","t":["Нехай, веде далі, Господи, викриє й покарає мене (докором) праведник, а ласкавість і послужливість грішника нехай не подає мені руки й не догоджає мені; бо краще й корисніше бич і викриття від праведника, ніж ласкавість, догідливість і солодкомовність грішника, що й означає олія. І жезл праведника значно корисніший для душі, ніж честь і доброчинність злого, як сказав і Григорій Богослов: корисніший бич праведника, ніж милість грішника, і жезл праведника кращий за честь злого. Додано «з милістю», бо праведник хоч і карає та викриває, але людинолюбно й милостиво; бо він дбає, щоб його брат, що грішить, не загинув, якщо не дістане належного викриття.","Прим.: Золотоустий: бачиш, яка тверда його душа в чесноті? Від праведників вона готова переносити з радістю й докори, а від беззаконних, хоч би вони говорили й щось приємне, відвертається. Чому? Бо ці й жалем часто гублять, а ті й суворістю виправляють; і у викритті тих міститься співчуття, а в співчутті цих — смерть. І дивись, як тут виразив апостольську пораду: викривай, забороняй, благай. Таке викриття в святих; так чинять і лікарі: вони не тільки розтинають, а й перев'язують. Якщо ж від злих треба відвертатися й тоді, коли вони милують, то коли ж треба зближуватися з ними? Явно, що ніколи. Тож коли злий і гроші дає, і обіцяє насолоди та почесті, відкидай і тікай; а праведника, хоч би він і докоряв, і насміхався, тримайся, бо він робить це з любові; адже й за словами Григорія Богослова сама суворість одного приємна через користь, а в іншого й милість підозріла через його злу вдачу. Феодорит: для мене, каже, бажаніше від праведників і щось образливе, що вони завдають для настанови й користі, ніж від грішників приємне, хоч би воно, на подобу олії, що намащує голову, обіцяло мені радісне життя; бо я краще хочу дістати покарання від праведників, ніж послуги від грішників. Безіменний: молюся, каже, щоб мені не мати спілкування з нечестивими, і віддаю перевагу співжиттю з праведником, хоча воно й здається важким через поводження з покаранням. Бо краще хочу приймати від праведника викриття, ніж від грішника ласкаве слово з обманом, хоч би він, намагаючись розм'якшити мене лестощами й незліченними чемностями, ніби олією помастив мою голову.","«Бо ще й молитва моя — проти вподобань їхніх»","Не тільки, веде далі, уникаю беззаконних і грішних людей і відвертаюся від спілкування з ними та від їхніх послуг, а ще й молюся при вподобаннях, тобто проти вподобань і злих бажань їхніх, як пояснює Золотоустий, розуміючи прийменник «в» (ἐν) як «проти», через заміну одного іншим. Я прошу, щоб їхні злі поради й шкідливі бажання не здійснилися, не збулися; бо саме це він називає вподобаннями.","Прим.: Слова Феодорита: я не тільки не заздрю їхньому благополуччю, а ще й молюся про зміну їхнього щастя, щоб, змінившись в успіху, вони змінилися й у злі. Тож під уподобаннями Феодорит тут розуміє добробут і благополуччя беззаконних і грішних. Згідно з цим і Золотоустий трохи нижче називає їх благополуччям."],"h":"Нехай карає мене праведник з милістю й викриває мене, а олія грішного нехай не помаже голови моєї"},{"v":"6","t":["Судді, каже, тобто володарі беззаконних, що начальствують і владарюють над ними, зникли, подібно до того каменя, що, кинутий у море, поглинається ним і стає невидимим, так що не лишається ні сліду, ні ознаки його. Це сказав той самий Давид і в іншому місці про нечестивого: і я пройшов, і ось не було його, і шукав його, і не знайшлося місця його (Пс. 36:36); цими словами виражає те, що нечестивого вириває з корінням, так що й імені його не лишається. А вираз «поглинуті» вжито замість «будуть поглинуті» — минулий час замість майбутнього: він пророкує цим про погибель беззаконних.","Прим.: Інший переклав так: будуть вирвані силою (рукою) каменя. А вираз ἐχόμενα, за словами Золотоустого, означає «поблизу», тобто як кинутий у море камінь стає невидимим, так і все їхнє благополуччя, зникнувши, не буде більше помітним. Феодорит: не за довгий, каже, час пропадуть і ті, хто мав верховну владу, подібно до підводних каменів, що ховаються в морських водах, і потонуть, інакше — будуть віддані забуттю.","«Почують слова мої, бо вони сильні»","Симмах переклав: почують слова мої (як) найприємніші: приймуть, каже, обізнані й розважливі до свого серця мої слова, як солодкі й приємні, бо вони істинні й корисні.","Прим.: Слова Євсевія: коли передбачене злим покарання збудеться, тоді мої слова здобудуть істинну достовірність, і розважливі приймуть їх як істинні й корисні."],"h":"Поглинуті були, як камінь, судді їхні"},{"v":"7","t":["Як, каже, твердий ґрунт землі, розораний плугом, кришиться й розсипається на різні грудки й частини землі, так і кості згаданих беззаконників розсипаються в гробі; бо саме його, за словами Феодорита, назвав адом."],"h":"Як брила землі розсипалася по землі, так розсипалися кості їхні при аді"},{"v":"8","t":["Очі, каже, моєї душі дивляться на Тебе, Господи, бо я всього себе покладав на Тебе. Тому не відбери в мене життя при гоніннях, яких зазнаю, і сильних злих задумах з боку ворогів.","Прим.: Золотоустого: хоч би, каже, спіткали нас незліченні біди — війни, чи смерть, чи брами аду, — ми триматимемося надії на Твою допомогу, як священного якоря. Орігена: погляд до Господа буває причиною єднання між тими, хто спрямовує свій погляд до неба; тому й сказано в однині: до Тебе, Господи, очі мої. А оскільки зло розсипає й кості, то ті, з ким це стається, названі множиною; тому й сказано в множині: розсипалися кості їхні. Застосуй до цього й заповідь, дану Адамові: у дозволі виражену в однині — їж, а в забороні — у множині: не їжте його (плоду)."],"h":"Бо до Тебе, Господи, Господи, очі мої; на Тебе я сподівався, не відбери душі моєї"},{"v":"9","t":["Збережи мене, просить, Господи, неушкодженим і постав мене вище за сітку, що її влаштували мої вороги, щоб упіймати мене, і від перешкод, покладених переді мною тими, хто чинить беззаконня. І сітками, і перешкодами називає хитрощі Саула та інших його ворогів."],"h":"Збережи мене від сітки, яку поставили мені, і від спокус тих, що чинять беззаконня"},{"v":"10","t":["Грішники, підсумовує, упадуть у свою сіть, поставлену ними, щоб упіймати мене, і будуть упіймані власним неводом. А оскільки в інших списках стоїть «його», то це означає, що грішники впадуть у Божу сіть.","«Один я, доки не перейду»","Я, каже, відокремлений від них, далекий від їхніх думок, і не так я відокремлений від них відстанню, як різницею в задумах і намірах. Не зійдуся ж я з ними, каже, доки не помру."],"h":"Упадуть у свою сіть грішники"}],"141":[{"v":"0","t":["Повчання Давидове, коли він був у печері й молився","Значення напису «повчання» ми вже не раз пояснили. Під «печерою» ж розуміє ту печеру, у якій Давид ховався, коли втікав від Саула. Коли Давид був у глибині печери, Саул, не знаючи цього, зупинився теж біля входу в печеру; тоді Давид, бачачи себе оточеним ворогами й ніби замкненим, промовив цю молитву до Бога."]},{"v":"1","t":["Оскільки він, щоб не бути відразу схопленим і не загинути, не міг кликати й кричати голосом, то під голосом тут треба розуміти напружений стан серця, що без слів кличе й мисленно молиться до Бога."],"h":"Голосом моїм до Господа я кликав, голосом моїм до Господа я молився"},{"v":"2","t":["Принесу, каже, Богові мою молитву.","«Печаль мою перед Ним сповіщу»","Знову повторює те саме. Принесу, каже, Йому замість молитви мою скорботу, що може схилити Господа до милості. Бо скорбота не тільки робить звичайно людей уважнішими й старанішими, а й дарує немалу сміливість перед Богом тому, хто з подякою переносить її. Вона здобуває велике право бути вислуханою."],"h":"Виллю перед Ним благання моє"},{"v":"3","t":["Це, каже, я роблю тому, що перебуваю в небезпеці смерті. Не чекаючи нізвідки допомоги, цілком звернувся до Бога.","«І Ти пізнав усі стежки мої»","Так я чиню, бо перебуваю в крайній небезпеці; але Тобі, Господи, відомі дороги мого життя, Ти знаєш, що я не зробив нічого з того, у чому через заздрість несправедливо обмовляють мене.","«На дорозі цій, якою я ходив, сховали сітку на мене»","На цій дорозі моєї втечі вони сховали сітку, таємно повставши проти мене й навмисно замкнувши мені вихід. Можна розуміти це також і про духовних ворогів, які не тільки на дорозі пороку розставляють сітки, а, що важливіше, і на дорозі чесноти, як, наприклад, у милосерді — сітку марнославства, а в терпінні — гордість і мрійливість.","Прим.: Тому й Сирах сказав: знай, що серед сіток ти йдеш і по мурах міських ходиш (Сир. 9:18). Феодорита: як мисливці стережуть стежки звірів і на них ставлять сітки, так і диявол для того, хто йде дорогою цнотливості, ставить сітку сластолюбства, для того, хто вправляється в милостині, — тенета марнославства, для некористолюбного — нагоди збудити сріблолюбство, і взагалі для кожного в житті — засідку, що легко ловить."],"h":"Коли знемагав у мені дух мій"},{"v":"4","t":["Праворуч від того, хто б'ється, звичайно стоять друзі, що допомагають і підтримують у битві. Тож Давид каже про себе: я дивився праворуч, і не було нікого, не тільки того, хто допоміг би, а навіть того, хто знав би мене, що, за словами Золотоустого, особливо збільшує біду.","Прим.: Золотого Святителя: небагатьом властиво бути поруч у бідах і допомагати, коли ці біди загрожують небезпеками. Тож коли побачиш, що біди зростають, не занепадай духом, а тим більше будь пильним. Бо Бог для того дозволяє їм зростати, щоб струсити з тебе недбалість, щоб пробудити тебе від сну. Тоді зайве відтинається, усе житейське здувається; тоді ти стаєш палкішим у молитвах, і всяка пристрасть, проганяна печаллю, легко перемагається. Феодорита: ні від кого, каже, ні з якого боку не бачив я допомоги. Бо правою стороною назвав тих, хто належить до доброзичливих.","«Загинула для мене втеча, і немає того, хто дбав би про душу мою»","Для мене, веде далі, нещасного, загинув спосіб утечі й спасіння, бо я замкнений у печері й не можу втекти, адже Саул біля входу в печеру; тому немає нікого, хто подбав би про порятунок мого життя від небезпеки."],"h":"Дивився я праворуч і придивлявся, і не було того, хто знав би мене"},{"v":"5","t":["Перебуваючи, веде далі, у такому замкненні й розпачі, я мисленно кликав до Тебе, Господи, своїм серцем (бо в присутності Саула я не міг кликати до Тебе чутно); і я сказав: Ти один — уся моя надія; і доки я на землі живих, тобто доки я живий і перебуваю з живими людьми, я маю тільки Тебе за частку, і багатство, і скарб, і іншої земної спадщини не маю жодної. Або: Ти моя спадщина й багатство на небі, бо небо — земля праведних, що завжди живі й ніколи не помирають.","Прим.: Слова Феодорита: часто божественний Давид називає своєю часткою Бога, і тепер зробив те саме: бо каже: я не маю жодної іншої допомоги, а маю тільки Тебе одного за опікуна й через Тебе бажаю досягти життя."],"h":"Я кликав до Тебе, Господи, я сказав: Ти надія моя, частка моя на землі живих"},{"v":"6","t":["Почуй, каже, Господи, мою молитву, якщо не за щось інше, то принаймні за моє велике лихо; бо смиренням Давид, за словами Феодорита, називає лихо й біду, яку й використовує як посередництво, щоб Бог почув його, і намагається нею схилити Владику до людинолюбства. І в іншому місці він же сказав: я був знедолений і упокорений до краю (Пс. 37:9).","Прим.: Золотоустого: прислівник «дуже» означає не осуд подій, а печаль і безсилля того, хто страждає: бо якщо, каже, Ти поглянеш на те, на що заслуговують гріхи, то невеликий утиск; а якщо на безсилля того, хто несе його, то надмірно великий. Бо Бог ніколи не карає за переступи так, як вони заслуговують.","«Визволи мене від тих, що женуть мене, бо вони стали сильніші за мене»","Визволи, веде далі, мене, Господи, від ворогів, що переслідують мене, бо вони стали сильніші за мене, замкнувши мене в такому місці, з якого я не можу втекти."],"h":"Почуй благання моє, бо я дуже упокорений"},{"v":"7","t":["В'язницею Давид називає ту печеру, у якій був замкнений, а душею — життя й усього себе. Отже, він каже: виведи мене, Господи, з цієї печери, щоб я міг дякувати імені Твоєму. У вищому ж значенні під в'язницею розуміється тіло, у якому зв'язана й ув'язнена душа.","Прим.: Тому й премудрий Ніл сказав: це тіло — в'язниця, бо зв'язує й тіснить ув'язнену в ньому душу. Тож ми молимося й кажемо: виведи з в'язниці душу мою, щоб прославити ім'я Твоє, — звісно, тому, що тіло заважає приносити Богові чисте прославлення. Бо якщо чуття прагне до чуттєвого, а розум до мисленного, Бог же наш — перший з мисленних предметів, то розум бажає звільнитися від чуттєвого, щоб наодинці бесідувати з одним Богом. Симмах же переклав так: постав поза ув'язненням душу мою.","«Мене чекають праведні, доки Ти не віддаси мені»","Акила переклав це так: мене чекатимуть (περιμενοῦσι) праведні, доки не віддаси мені. Праведні, каже, чекають мене, сподіваючись, що я звільнюся від бід і спокус, і чекатимуть, доки Ти, Господи, не віддаси мені за це лихо й утиск, яких я несправедливо зазнаю. Бо такі душі святих і праведних: вони, за словами Золотоустого, з нещасними сумують, а зі щасливими радіють.","Прим.: Золотоустого: називає віддачею за дні утиску. Бо й це немалий подвиг — переносити скорботу з подякою; тому й майбутню нагороду за неї називає віддачею. Тож не знесилюймося в скорботах, а молімося, бо через це й учинені гріхи скидаємо з себе, а якщо ми вчинили якусь правду, можемо зробити її тим світлішою. Скорбота часто перемагає й природу. Бо й вода, що прагне вниз і тече, швидко піднімається вгору; а це, звісно, буває й з людьми: бо ті, хто легко переносить скорботи, через це стають вищими, хоч би раніше були й дуже схильні до земного, низькі й похилені до землі, і дістають від неї багато користі.","Прим.: Феодорит каже, що Симмах переклав: ім'я Твоє увінчають праведні, коли Ти зробиш мені добро; бо зроблене мені добро праведні приймуть для себе як запоруку спасіння й прославлять Тебе як праведного Суддю."],"h":"Виведи з в'язниці душу мою, щоб прославити ім'я Твоє"}],"142":[{"v":"0","t":["Псалом Давидів, коли гнав його син його Авессалом","У багатьох списках цей псалом без напису. І цього напису немає ні в єврейській Псалтирі, ні в її перекладачів. Утім, він, за запевненням Феодорита, правдивий. Цей псалом пасує тим, кого гнітять скорботи й спокуси. У деяких списках є згаданий напис, і 3-й псалом має подібний напис, але не той самий: Псалом Давидів, коли втікав від лиця Авессалома, сина свого.","Прим.: За словами Євсевія й Афанасія, цей псалом стосується й людства, яке гонить і гнітить сатана; воно тут молиться про пришестя Єдинородного й про своє визволення через Нього."]},{"v":"1","t":["Вислухай, Господи, починає, мою молитву й виклад потреби в істині Твоїй, тобто оскільки Ти істинний: бо Ти обіцяв вислуховувати тих, хто кличе Тебе щиро й від усього серця, як Ти обіцяв зокрема й мені, сказавши: покличе Мене, і вислухаю його (Пс. 90:15).","Прим.: Молитва, за Золотоустим, — це і прохання словами, і також обітниця; тому й Сирах каже: не повторюй слів молитви твоєї (Сир. 7:14), — не в тому значенні, що не слід повторювати слів у молитві, а в тому, щоб не відкладати наших обітниць Богові. А тут молитвою назвав прохання. Інший, тобто Никита: усіх чує Господь, але не всіх вислуховує. Та якщо ми вислуховуємо нужденних, то будемо вислухані й самі. Інший: тих, хто кличе Бога істинно, Бог і вислуховує істинно; це ті, хто любить Його, слухняний Йому й поклоняється Йому духом і істиною. А Афанасій істиною й правдою називає Сина: бо просить, щоб був вислуханий через Істину й Правду, якою є Єдинородний.","«Вислухай мене в правді Твоїй»","Вислухай, веде далі, Господи, мене, як праведний і такий, що не терпить заподіяння кривд, не тільки з боку дітей їхнім батькам, а й однієї людини іншій. Але Золотоустий істиною тут називає істинну Божу милість, а правдою — Боже людинолюбство: бо один Бог істинно милує, і одна Божа правда розчинена людинолюбством, адже в людській правді немає милості.","Прим.: Золотоустий доводить це й потопом: бо Бог покарав знищених потопом милостиво, і вони не дістали належного покарання."],"h":"Господи, вислухай молитву мою, почуй благання моє в істині Твоїй"},{"v":"2","t":["Не судися, каже, і не входь у змагання з рабом Твоїм, Господи; бо якщо Ти почнеш судитися зі мною, то Ти, без сумніву, виявишся праведним, а я, навпаки, неправим і грішником; і в цьому Твоєму суді Ти, звісно, переможеш, а я безперечно буду переможений.","Прим.: Той самий: тут викладає причину Божого суду з людьми. Бо оскільки багато хто з безглуздих приписує свої гріхи Богові з диявольського навіяння, то Бог, викорінюючи такий звичай, часто нагадує про Свій суд із ними: слухайте, гори! бо суд у Господа з народом Його (Мих. 6:2); і слухайте, безодні й основи землі; також слухай, небо, і почуй, земле; і Йов так само, хоча був не такого духу, як юдей, однак казав: о якби був посередник, і викривач, і той, хто вислухав би обох (Йов 9:33). Тому й каже йому Бог: запитаю тебе, а ти відповідай Мені. А оскільки він, жахнувшись (цього), сказав: навіщо мені ще судитися? покладу руку на уста свої (Йов 39:34; 40:2), то Він каже йому: ні, але підпережи, як муж, стегна свої, чим майже нагадує його слова: чого ти хотів судитися зі Мною? ось Я готовий судитися. Тому й Давид тепер молиться, щоб йому не ввійти в суд із Богом.","«Бо не виправдається перед Тобою жоден живий»","Не сказав просто, що жоден живий не виправдається, а що не виправдається ніхто перед Тобою, тобто в суворому суді й докладному змаганні та суперечці на Твоєму праведному суді, Боже! Або при порівнянні мене на суді з Твоїми благодіяннями й заповідями. Знаючи це, і блаженний Йов каже: тому я докорив собі, і знемігся, і вважав себе землею й попелом (Йов 42:6); і ще: руку покладу на уста свої; раз я говорив, а вдруге не буду (Йов 39:34-35). Подивися й у 129-му псалмі пояснення слів: якщо на беззаконня зважатимеш, Господи, Господи, то хто встоїть? А сказав «жоден живий» замість «кожна людина, що має участь у житті й жила чи перебуває в цьому світі». Тому, як каже апостол, ми виправдовуємося даром, Божою благодаттю, через викуплення в Ісусі Христі (Рим. 3:24).","Прим.: Феодорит: бо якщо застосуєш вимогу встановлених Тобою законів до людського життя, то виявиться, що ніхто не жив за ними. Якщо ж ще вкажеш на Твої благодіяння й на те, скільки благ Ти дав людям, то яка людська правда може зрівнятися з Твоїми дарами? Як лахміття жінки, що сидить (за законом), уся наша правда. Тому, за словами Никити, святі не знають, що сказати, і кажуть: що віддам Господеві? Тож не за беззаконнями нашими суди нас."],"h":"І не входь у суд з рабом Твоїм"},{"v":"3","t":["Попереднє «бо» означає причину, а це («бо») — оповідне. Ворогом тут Давид називає в оповідному значенні Авессалома, а у вищому — диявола.","Прим.: Золотоустого: бо диявол безупинно переслідує. Як же нам звільнитися від цих гонінь? Якби ми знайшли місце, куди можна було б увійти! Але де таке місце? На небі? Але як можна піднятися тепер на небо? Послухай Павла, що каже, що й у поєднанні з плоттю можна перебувати там: про горнє, каже, думайте; також: наше життя — на небесах.","«Принизив до землі життя моє»","Чуттєвий мій ворог Авессалом повалив, каже, мене на землю, не тільки тому, що я схилився до землі й зігнувся під тягарем нещасть, а й тому, що й сиджу, і сплю на землі, і (ходжу) босий і в сльозах, як утікач і мандрівник по горах. Понад те й мисленний мій ворог диявол, скинувши з небесних предметів, повалив мене в земні й дольні. Утім, вираз «приниження» (упокорення) має багато значень, за поясненням Золотоустого. Бо означає не тільки чесноту смирення, а й те, що походить від бід, і від гріхів, і від гордості, і від сріблолюбства. Бо приниження, що його творить сріблолюбство, і найменшу та найдрібнішу монету уявляє собі великою сумою, а дрібне й нічого не варте вважає бажаним і дорогоцінним, як і малі діти уявляють чимось великим кісточки й свищики. Тут Давид говорить про приниження, що походить від бід.","«Посадив мене в темряві, як мертвих віку»","Чуттєвий, веде далі, і мисленний мій ворог кинув мене в темряву печалі й затьмарив мій розум. А вираз «як мертвих від віку» вжито, щоб показати затьмарення найвищого ступеня й сили; бо не сказав просто «як мертвих», а з додаванням «віку», указуючи цим на давніх, щоб з особливою силою показати тягар і велич своєї скорботи й тісноти; бо давні мерці перебувають у глибокій темряві, як засипані безліччю землі.","Прим.: Слова Золотоустого: говорить про подвійну біду: що посадив у темряві і як мертвих від віку. Оскільки й у темному місці можна щось робити при запаленому світильнику, то, щоб з більшою силою показати надмір бід, ім'ям мертвих посилив вираз печалі. Такий стан тих, хто живе в гріхах: перебуваючи в них, вони подібні до мертвих у темряві."],"h":"Бо переслідував ворог душу мою"},{"v":"4","t":["Душа моя, каже, сумує в мені й у бездіяльності, або знемогла від надмірної печалі, а серце моє стривожилося й стиснулося від утиску.","Прим.: Євсевія: показує, від чого він занепав духом. Від чого ж? Від того, що його серце через підступи бісів прийшло в неспокій і тривогу.","Прим.: Божественного Золотоустого: виражає великий тягар печалі тривогою серця й тим, що неможливо було відкрити її іншим, щоб дістати якусь розраду. І Василій у слові на гнівливих каже: у мені стривожилося серце моє, тобто пристрасть (гніву) не виявлялася назовні, а була подібна до хвиль, що розбиваються біля берегів і розстеляються. Інший, тобто Никита, каже: я не оголошував своєї печалі, вважаючи за краще ховати, ніж оголошувати стороннім."],"h":"І занепав у мені дух мій, у мені стривожилося серце моє"},{"v":"5","t":["Я, веде далі, згадав, Господи, ті давні роки, коли, живучи як слід, я догоджав Богові, або згадав ті літа, коли й наші праотці мали успіх і щастя. Або, навпаки, згадав ті роки, коли й наші предки страждали від різних бід. Бо спогад про біди інших дає душі немалий спокій.","«Роздумував я про всі діла Твої, про творіння рук Твоїх я роздумував»","Я, веде далі, роздумував про всі діла Твої, Господи, міркуючи в собі про чудеса, звершені Тобою в різні часи; тому, пам'ятаючи про тих, кого Ти славно визволив від різних бід, я діставав із цього розраду; я так само роздумував у своєму розумі й про творіння рук Твоїх і, бачачи, що всі вони нині користуються Твоїм промислом і Твоєю благістю, я діставав із цього в своїх лихах добрі надії, тобто що Ти не залишиш і мене без опіки й допомоги, як того, хто страждає й терпить такі в повному значенні біди.","Прим.: Тому Золотоустий каже: немала розрада й від знання минулого й теперішнього: бо оскільки Бог і теперішніми подіями керує за тими самими законами, за якими керував і минулими, то найбільшу розраду в теперішньому може дати спогад про минуле. Погляньте, каже, на давні роди й побачите: хто з вірою в Господа посоромився? (Сир. 2:10); і Павло каже: усе це ставалося з ними як приклад для нас і написано на науку нам (1 Кор. 10:11). І не тільки від спогаду чужого, а часто й від свого можемо мати користь, як каже апостол: згадайте попередні дні (ваші), коли ви, бувши просвітлені, витримали великий подвиг страждань (Євр. 10:32). Тому й цей (Давид) не просто каже «я згадав», а й «роздумував», тобто я, як своїм ділом, займався глибоким роздумом. Бо велику розраду й любомудрість може дати нам і розповідь, що міститься в Писаннях. Тому й Павло казав: щоб ми терпінням і розрадою з Писань зберігали надію (Рим. 15:4). Феодорита: я, каже, подумав, від яких великих бід Ти звільнив наших предків і не дав ворогам перемогти їх, подумав про те, що було з Авраамом, що з Ісааком, що з Яковом, що з Йосифом, що з Мойсеєм; і я дістав із цього розраду."],"h":"Згадав я дні давні"},{"v":"6","t":["Я, пояснює, простягав до Тебе свої руки, Господи, палко молячись і просячи Тебе; і як безводна земля прагне чуттєвого дощу, так і душа моя, Господи, висохнувши від спокус і пристрастей, прагне Твоєї благодаті й допомоги.","Прим.: Не сказав, каже Золотий Витія, «я простягнув», а «я розпростер (підняв)», чим показує велику сердечну прихильність: бо в нього вона мало не виривалася з тіла в пориві до Нього."],"h":"Простягнув я до Тебе руки мої; душа моя, як земля безводна, до Тебе"},{"v":"7","t":["Швидко, додає, вислухай мою молитву, Господи, бо моя душа мало не виходить і не лишає мене мертвим.","Прим.: Слова Золотоустого: що ти кажеш? Ти квапиш лікаря до лікування? Зовсім ні. Але й це властиво душам, пригніченим скорботою, як роблять і хворі, — просити лікарів, хоч час і не дозволяє дати швидке звільнення. Тому, додаючи причину, він каже: знеміг дух мій.","«Не відвертай лиця Твого від мене, щоб не уподібнився я тим, що сходять у рів»","Не відвертай, веде далі, Господи, лиця Твого від мене й не залиш мене: бо якщо Ти залишиш мене, я швидко помру й уподібнюся мертвим; бо мертві відходять у рів, тобто в гроб; і справді, хто позбавлений Твоєї допомоги й благодаті, той мертвий. А відвертає Бог Своє лице, коли позбавляє злих людей Свого милостивого погляду й промислу, після чого вони чинять діла, негідні Божого погляду; тому Авакум сказав, що чисте око не бачить зла: чисте око не може дивитися на зло (Ав. 1:13).","Прим.: Слова Євсевія: доки лице Твоє удостоює мене свого просвітлення, доти світло Твоє в мені, і доти я можу казати: знаменувалося на нас світло лиця Твого. А коли відвернеш лице Твоє, що означає гнів, тоді мене пізнає темрява, і я уподібнюся тим, що падають з висоти в рів зла. Феодорита: бо якщо Ти погребуєш через гріх цим моїм принизливим проханням, то я негайно буду відданий смерті. Бо ровом, за відомим зворотом мови, назвав смерть; адже як неможливо ув'язненому в рові (у темниці) вийти без допомоги інших, так і померлому — ожити без Божої волі."],"h":"Швидко вислухай мене, Господи, знеміг дух мій"},{"v":"8","t":["Сповісти, каже, і відкрий, Господи, швидко (бо це означає «вранці»), що Ти явиш мені милість, щоб і до того, як скуштую Твоєї милості на досвіді й ділом, я міг утішитися вже самою цією звісткою й обітницею Твоєї милості. На якій же підставі Ти можеш відкрити мені, що явиш мені Свою милість? На тій, відповідає, що я цілком сподівався на Тебе: така надія від усього серця здатна швидко притягти Божу милість.","Прим.: За словами Афанасія, молиться про наближення ранкового Христового воскресіння, яким ми помилувані.","«Скажи мені, Господи, дорогу, якою піду, бо до Тебе я підніс душу мою»","Чому Давид просить тут, щоб Господь відкрив йому дорогу спасіння, тоді як і природний закон, і писаний навчають про це? Відповідаємо: Давид просить цього або тому, що природний закон, написаний у сумлінні, завалений і покритий гріхом, — тому, каже, мені потрібне його оновлення Твоєю благодаттю й Твоєю настановою; або тому, що людина не знає багатьох корисних речей; тому й просить тут (Давид) Бога безпосередньо відкрити їх. Тому й Павло пише: бо ми не знаємо, про що молитися, як належить (Рим. 8:26). До Тебе, каже, прагну й прилипаю; тож яви мені дорогу спасіння, ходячи якою непогрішно, я можу прийти до Тебе.","Прим.: Того ж Афанасія: Давид молиться, щоб йому було сповіщене євангельське вчення. Золотоустого: «до Тебе я підніс душу мою» означає: до Тебе прагну, на Тебе дивлюся."],"h":"Дай мені почути вранці милість Твою, бо на Тебе я сподівався"},{"v":"9-10","t":["Не сказав «навчи мене волі Твоєї», а, за зауваженням Золотоустого, «навчи мене чинити волю Твою»; бо блаженний чи щасливий не той лише, хто знає Божу волю, а той, хто виконує її, адже знати Божу волю легко, а виконувати її важко; тому, за словами Євсевія, потрібна настанова й допомога від Бога.","Прим.: Слова Феодорита: молю Тебе й про те, щоб мені не тільки знати, що Тобі до вподоби, а й чинити вгодне Тобі, бо я знаю, що Ти Бог мій і Владика.","«Дух Твій благий поведе мене на землю рівну»","Благий, каже, і Святий Дух Твій, Господи, поведе мене на пряму й рівну дорогу, якою є чеснота: вона пряма, бо непогрішно веде людей до спасіння, і рівна, бо вільна від перешкод і урвищ, якими є пристрасті й гріхи.","Прим.: Золотоустого: бачиш, як ми пізнаємо, як навчаємося проходити дорогу дією Святого Духа? Тому й Павло казав: а нам Бог відкрив Духом Своїм. Божественного Василія: Бог називається й справді є благий. Благий також і Дух Святий, що має благість не набуту, а таку, що міститься в самій Його природі."],"h":"Визволи мене від ворогів моїх, Господи, до Тебе я прибіг. Навчи мене чинити волю Твою, бо Ти Бог мій"},{"v":"11","t":["Ти, підсумовує, Господи, оживиш мене не за мою чесноту, а заради імені Твого святого, бо Ти звешся людинолюбним і милостивим. І в 113-му псалмі так само сказано: не нам, Господи, не нам, а імені Твоєму дай славу.","«Правдою Твоєю виведеш із печалі душу мою»"],"h":"Імені Твого ради, Господи, оживиш мене"},{"v":"12","t":["Про ту правду, про яку Давид сказав на початку цього псалма, тепер повторює й тут; а названу на початку істину тут називає милістю. А винищення й погублення мисленних ворогів означає їхнє прогнання й знищення, залежно від слів і бажання того, хто говорить. Далі вирази «оживиш», «виведеш», «винищиш» і «погубиш» поставлено в майбутньому часі, як вимовлені пророчо; утім, їх можна прийняти й у значенні бажального способу, замість «оживи, виведи, винищ і погуби».","Прим.: Слова Євсевія: питається: як ті самі дістають милість і знищуються? Як, як не милістю, властивою Богові? Просить про сокрушення своїх ворогів, кажучи: не тому, що я гідний того, а з Твого людинолюбства звільни мене від моїх противників, звільни від тих, хто задумує зло; дай хоч невеликий відпочинок від скорботи. Феодорита: це сказав і в 135-му псалмі: що вразив Єгипет з первістками його, бо повік милість Його. Так каже й тут: милістю Твоєю винищиш ворогів моїх. Бо милість до скривдженого спричиняє загибель кривдникові. Так і добрий хлібороб вириває терни з корінням, а рослини, ним посаджені, поливає й удобрює й обробляє довкола них землю.","Тому, додає, Ти звільниш мою душу, Господи, від скорботи й винищиш моїх ворогів, що я раб Твій і стараюся служити Тобі й зберігати всі Твої повеління, Владико!","Прим.: Золотоустого: дивись, знову причина загибелі ворогів, каже, та, що я раб Твій. Бо неможливо дістати прохане просто так, а скрізь треба готувати себе до отримання проханого й докладати те, що залежить від нас, і тоді приступати з молитвою, бо однієї молитви нам недостатньо. І юдеї молилися, але почули (відповідь): хоч примножите ваші благання, не вислухаю вас. І чому ти дивуєшся, що юдеї не були вислухані, коли й Єремія, молячись за них, дістав грізну відповідь, і раз, і вдруге почув: не молись за цей народ, бо не вислухаю тебе."],"h":"І милістю Твоєю винищиш ворогів моїх, і погубиш усіх, хто утискає душу мою, бо я раб Твій"}]};
